window.__texto({"id": "744156846", "paragrafos": [{"c": "identifica", "t": "PORTARIA Nº 633, DE 5 DE NOVEMBRO DE 2026 (*)"}, {"c": "ementa", "t": "Aprova o Regulamento Técnico da Qualidade e os Requisitos de Avaliação da Conformidade para Equipamentos de Aquecimento Solar de Água - Consolidado."}, {"c": "dou-paragraph", "t": "O PRESIDENTE DO INSTITUTO NACIONAL DE METROLOGIA, QUALIDADE E TECNOLOGIA - INMETRO, SUBSTITUTO, no exercício da competência que lhe foi outorgada pelos artigos 4º, § 2º, da Lei nº 5.966, de 11 de dezembro de 1973, e 3º, incisos I e IV, da Lei nº 9.933, de 20 de dezembro de 1999, combinado com o disposto no artigo 18, inciso V, do Anexo I ao Decreto nº 11.221, de 5 de outubro de 2022, considerando o Processo SEI nº 0052600.010312/2020-18, resolve:"}, {"c": "dou-paragraph", "t": "Objeto e âmbito de aplicação"}, {"c": "dou-paragraph", "t": "Art. 1º Fica aprovado o Regulamento Consolidado para Equipamentos de Aquecimento Solar de Água, na forma do Regulamento Técnico da Qualidade, dos Requisitos de Avaliação da Conformidade e das Especificações para o Selo de Identificação da Conformidade, fixados, respectivamente, nos Anexos I, II e III desta Portaria."}, {"c": "dou-paragraph", "t": "Art. 2º O Regulamento Técnico da Qualidade, estabelecido no Anexo I, determina os requisitos, de cumprimento obrigatório, referentes à segurança e desempenho do produto."}, {"c": "dou-paragraph", "t": "Art. 3º Os fornecedores de equipamentos de aquecimento solar de água deverão atender integralmente ao disposto no presente Regulamento."}, {"c": "dou-paragraph", "t": "Art. 4º Os equipamentos de aquecimento solar de água, objeto deste Regulamento, deverão ser fabricados, importados, distribuídos e comercializados, de forma a não oferecer riscos que comprometam a segurança do usuário, independentemente do atendimento integral aos requisitos ora publicados."}, {"c": "dou-paragraph", "t": "§ 1º Aplica-se o presente Regulamento aos equipamentos de aquecimento solar de água disponibilizados no mercado nacional, incluindo:"}, {"c": "dou-paragraph", "t": "I - coletores solares térmicos;"}, {"c": "dou-paragraph", "t": "II - reservatórios termossolares fechados, de alta pressão, baixa pressão ou de nível, com ou sem respiro, com volume padronizado menor ou igual a 1000 litros; e"}, {"c": "dou-paragraph", "t": "III - sistemas acoplados, excetuando-se aqueles cujos reservatórios não observem as restrições acima."}, {"c": "dou-paragraph", "t": "§ 2º Encontram-se excluídos do cumprimento das disposições previstas neste Regulamento:"}, {"c": "dou-paragraph", "t": "I - concentradores solares (tais como os tipos parabólicos, de disco, torre e Fresnel); e"}, {"c": "dou-paragraph", "t": "II - reservatórios termossolares abertos."}, {"c": "dou-paragraph", "t": "§ 3º Tendo em vista a diversidade de produtos abrangidos por esta Portaria, o detalhamento quanto ao referido escopo pode ser consultado em www.inmetro.gov.br."}, {"c": "dou-paragraph", "t": "Art. 5º A cadeia produtiva de equipamentos de aquecimento solar de água fica sujeita às seguintes obrigações e responsabilidades:"}, {"c": "dou-paragraph", "t": "I - o fabricante nacional deve fabricar e disponibilizar, a título gratuito ou oneroso, equipamentos de aquecimento solar de água conforme o disposto neste Regulamento;"}, {"c": "dou-paragraph", "t": "II - o importador deve importar e disponibilizar, a título gratuito ou oneroso, equipamentos de aquecimento solar de água conforme o disposto neste Regulamento;"}, {"c": "dou-paragraph", "t": "III - os demais entes da cadeia produtiva e de fornecimento de equipamentos de aquecimento solar de água, incluindo o comércio em estabelecimentos físicos ou em meio eletrônico, devem manter a integridade do produto, das suas marcações obrigatórias, preservando o atendimento aos requisitos deste Regulamento."}, {"c": "dou-paragraph", "t": "Parágrafo único. Caso um ente exerça mais de uma função na cadeia produtiva e de fornecimento, entre as anteriormente listadas, suas responsabilidades são acumuladas."}, {"c": "dou-paragraph", "t": "Art. 6º O comércio de equipamentos de aquecimento solar de água, em estabelecimentos físicos ou em meio eletrônico, fica sujeito ainda às seguintes obrigações:"}, {"c": "dou-paragraph", "t": "§ 1º Os produtos deverão, no ponto de venda, ostentar a Etiqueta Nacional de Conservação de Energia (ENCE), de forma claramente visível ao consumidor, sem que sua visualização seja obstruída por qualquer outra informação anexada pelos fornecedores."}, {"c": "dou-paragraph", "t": "§ 2º No comércio em meio eletrônico, incluindo sites de venda, busca e comparação de produtos, é de responsabilidade do administrador do site disponibilizar a ENCE ou, alternativamente, as informações nela constantes em formato de texto, em todas as páginas onde haja oferta ou exibição do produto, de forma ostensiva, clara e unívoca junto à imagem ou identificação do modelo do produto."}, {"c": "dou-paragraph", "t": "§ 3º Em catálogos de venda e em material publicitário físico ou em meio eletrônico, a ENCE ou, alternativamente, as informações nela constantes em formato de texto, devem estar disponíveis de forma clara e unívoca junto à imagem ou identificação do modelo do produto."}, {"c": "dou-paragraph", "t": "Exigências Pré-Mercado"}, {"c": "dou-paragraph", "t": "Art. 7º Os equipamentos de aquecimento solar de água, fabricados, importados, distribuídos e comercializados em território nacional, a título gratuito ou oneroso, devem ser submetidos, compulsoriamente, à avaliação da conformidade, por meio do mecanismo de certificação, observado os termos deste Regulamento."}, {"c": "dou-paragraph", "t": "§ 1º Os Requisitos de Avaliação da Conformidade para Equipamentos de Aquecimento Solar de Água estão fixados no Anexo II desta Portaria."}, {"c": "dou-paragraph", "t": "§ 2º A certificação não exime o fornecedor da responsabilidade exclusiva pela segurança do produto."}, {"c": "dou-paragraph", "t": "Art. 8º Após a certificação, os equipamentos de aquecimento solar de água, importados, distribuídos e comercializados em território nacional, a título gratuito ou oneroso, devem ser registrados no Inmetro, considerando a Portaria Inmetro nº 258, de 6 de agosto de 2020, ou substitutiva."}, {"c": "dou-paragraph", "t": "§ 1º A obtenção do registro é condicionante para a autorização do uso do Selo de Identificação da Conformidade nos produtos certificados e para sua disponibilização no mercado nacional."}, {"c": "dou-paragraph", "t": "§ 2º Os modelos de Selo de Identificação da Conformidade aplicáveis para equipamentos de aquecimento solar de água, encontram-se no Anexo III desta Portaria."}, {"c": "dou-paragraph", "t": "Art. 9º Os equipamentos de aquecimento solar de água abrangidos pelo Regulamento ora aprovado, estão sujeitos ao regime de licenciamento de importação não automático, devendo o importador obter anuência junto ao Inmetro, considerando a Portaria Inmetro nº 137, de 24 de março de 2022, ou substitutiva."}, {"c": "dou-paragraph", "t": "Vigilância de Mercado"}, {"c": "dou-paragraph", "t": "Art. 10. Os equipamentos de aquecimento solar de água, objeto deste Regulamento, estão sujeitos, em todo o território nacional, às ações de vigilância de mercado executadas pelo Inmetro e entidades de direito público a ele vinculadas por convênio de delegação."}, {"c": "dou-paragraph", "t": "Art. 11. Constitui infração a ação ou omissão contrária ao disposto nesta Portaria, podendo ensejar as penalidades previstas na Lei nº 9.933, de 20 de dezembro de 1999."}, {"c": "dou-paragraph", "t": "Art. 12. O fornecedor, quando submetido a ações de vigilância de mercado, deverá prestar ao Inmetro, quando solicitado, as informações requeridas em um prazo máximo de 15 dias."}, {"c": "dou-paragraph", "t": "Prazos e disposições transitórias"}, {"c": "dou-paragraph", "t": "Art. 13. A publicação desta Portaria não implica na necessidade de que seja iniciado novo processo de certificação com base nos requisitos ora consolidados."}, {"c": "dou-paragraph", "t": "Parágrafo único. Os certificados já emitidos deverão ser revisados, para referência à Portaria ora publicada, na próxima etapa de avaliação."}, {"c": "dou-paragraph", "t": "Art. 14. Os requisitos relacionados à periodicidade da auditoria e ensaios de manutenção, previstos nos subitens 6.2.2.1 e 6.2.2.2 do Anexo II desta Portaria deverão incidir sobre os certificados emitidos com base na Portaria Inmetro nº 352, de 2012, considerando-se como referência a data de concessão."}, {"c": "dou-paragraph", "t": "Cláusula de revogação"}, {"c": "dou-paragraph", "t": "Art. 15. Ficam revogadas, na data de vigência desta Portaria, as Portarias Inmetro:"}, {"c": "dou-paragraph", "t": "I - nº 420, de 4 de outubro de 2021, publicada no Diário Oficial da União de 14 de outubro de 2021, seção 1, página 42 a 51;"}, {"c": "dou-paragraph", "t": "II - nº 333, de 28 de agosto de 2023, publicada no Diário Oficial da União de 24 de outubro de 2024, seção 1, página 24; e"}, {"c": "dou-paragraph", "t": "III - nº 215, de 6 de junho de 2024, publicada no Diário Oficial da União de 7 de junho de 2024, seção 1, página 31 a 34."}, {"c": "dou-paragraph", "t": "Vigência"}, {"c": "dou-paragraph", "t": "Art. 16. Esta Portaria entra em vigor na data de sua publicação no Diário Oficial da União."}, {"c": "assina", "t": "MARCIO ANDERSON FELIX MUNIZ"}, {"c": "dou-paragraph", "t": "ANEXO I REGULAMENTO TÉCNICO DA QUALIDADE PARA EQUIPAMENTOS DE AQUECIMENTO SOLAR DE ÁGUA"}, {"c": "dou-paragraph", "t": "1. OBJETIVO"}, {"c": "dou-paragraph", "t": "Este Regulamento Técnico da Qualidade estabelece os requisitos obrigatórios para equipamentos de aquecimento solar de água a serem atendidos por toda cadeia fornecedora do produto no mercado nacional."}, {"c": "dou-paragraph", "t": "Nota: Neste regulamento, os \"equipamentos de aquecimento solar de água\" são denominados \"equipamentos\", os \"coletores solares\" são denominados \"coletores\" e os \"reservatórios termossolares\" são denominados \"reservatórios\"."}, {"c": "dou-paragraph", "t": "3. DEFINIÇÕES"}, {"c": "dou-paragraph", "t": "3.1 Absorvedor"}, {"c": "dou-paragraph", "t": "Componente de um coletor solar que absorve a energia radiante e transfere essa energia na forma de calor para um fluido."}, {"c": "dou-paragraph", "t": "3.2 Aparelho classe 0I"}, {"c": "dou-paragraph", "t": "Aparelho que tem pelo menos isolação básica em todas as suas partes e é dotado de terminal de aterramento, mas cujo cordão de alimentação não tem condutor de aterramento e cujo plugue não tem contato de aterramento."}, {"c": "dou-paragraph", "t": "3.3 Aparelho classe I"}, {"c": "dou-paragraph", "t": "Aparelho no qual a proteção contra choque elétrico não é assegurada somente por isolação básica, mas inclui uma precaução adicional de segurança, de modo que as partes acessíveis condutivas são ligadas ao condutor de aterramento da fiação fixa da instalação, de tal maneira que essas partes acessíveis não possam tornar-se vivas no caso de uma falha da isolação básica."}, {"c": "dou-paragraph", "t": "3.4 Area bruta do coletor (AG)"}, {"c": "dou-paragraph", "t": "Área máxima projetada do coletor completo, excluindo qualquer integrante do meio de montagem e ligações das tubulações do fluido."}, {"c": "dou-paragraph", "t": "3.5 Área de abertura ( A aber )"}, {"c": "dou-paragraph", "t": "Área máxima projetada através da qual a radiação solar não concentrada entra no coletor."}, {"c": "dou-paragraph", "t": "Nota: A área de abertura não inclui nenhuma parte transparente protegida da radiação solar quando esta radiação incide na direção perpendicular ao plano de projeção que define a área de abertura."}, {"c": "dou-paragraph", "t": "3.6 Área do absorvedor com concentração"}, {"c": "dou-paragraph", "t": "Área da superfície do absorvedor que é concebida para absorver radiação solar."}, {"c": "dou-paragraph", "t": "Nota: A área do absorvedor não inclui qualquer parte do absorvedor permanentemente rastreada da radiação solar."}, {"c": "dou-paragraph", "t": "3.7 Área do absorvedor sem concentração"}, {"c": "dou-paragraph", "t": "Área máxima projetada de um absorvedor."}, {"c": "dou-paragraph", "t": "Nota: A área de absorção inclui somente a parte do absorvedor que recebe radiação solar perpendicular ao plano de projeção."}, {"c": "dou-paragraph", "t": "3.8 Cobertura do coletor"}, {"c": "dou-paragraph", "t": "Material(is) transparente(s), ou translúcido(s), que cobre(m) a absorção de calor para a redução das perdas e proporciona(m) proteção meteorológica."}, {"c": "dou-paragraph", "t": "3.9 Coletor concentrador"}, {"c": "dou-paragraph", "t": "Coletor solar que usa refletores, lentes ou outros elementos ópticos para direcionar e concentrar a radiação solar passando pelas aberturas do absorvedor."}, {"c": "dou-paragraph", "t": "Nota: Um coletor a montante fixo, provido de um espelho, ou um coletor tubular a vácuo com um refletor por trás dos tubos, é um coletor de concentração."}, {"c": "dou-paragraph", "t": "3.10 Coletor concentrador composto parabólico (CPC)"}, {"c": "dou-paragraph", "t": "Coletor que utiliza segmentos de refletor parabólico de radiação solar concentrada."}, {"c": "dou-paragraph", "t": "Nota 1: Os segmentos refletores parabólicos e todos os segmentos de radiação incidente sobre a abertura incluindo intervalos dos ângulos de incidência estabelecem o ângulo de aceitação do concentrador."}, {"c": "dou-paragraph", "t": "Nota 2: O termo CPC é aplicado a muitos concentradores sem imagem, mesmo por meio da representação gráfica que pode diferir geometricamente da parabólica."}, {"c": "dou-paragraph", "t": "3.11 Coletor solar térmico"}, {"c": "dou-paragraph", "t": "Dispositivo projetado para absorver a radiação solar e transferir a energia térmica produzida para um fluido que passa pelo equipamento."}, {"c": "dou-paragraph", "t": "Nota: Nesse regulamento, os coletores serão considerados conforme sua aplicação, sendo banho, quando comercializado para aquecimento da água para banho e afins, ou piscina, quando comercializado para aquecimento de água da piscina."}, {"c": "dou-paragraph", "t": "3.12 Coletor solar aberto"}, {"c": "dou-paragraph", "t": "Coletor solar cujo componente responsável pela absorção da radiação solar não fica protegido das intempéries por cobertura transparente."}, {"c": "dou-paragraph", "t": "3.13 Coletor solar fechado"}, {"c": "dou-paragraph", "t": "Coletor solar cujo componente responsável pela absorção da radiação solar fica protegido das intempéries por cobertura transparente."}, {"c": "dou-paragraph", "t": "3.14 Coletor tubo a vácuo"}, {"c": "dou-paragraph", "t": "Coletor que utiliza tubo transparente, geralmente de vidro, com um espaço em vácuo entre a parede do tubo externo e o absorvedor."}, {"c": "dou-paragraph", "t": "Nota: A absorção pode ser constituída por um tubo no interior ou pode ser de outra forma, com meios de remoção da energia térmica."}, {"c": "dou-paragraph", "t": "3.15 Dia padrão"}, {"c": "dou-paragraph", "t": "Fixação, a partir dos dados obtidos em um dia pré-determinado no ano, dos valores da radiação solar global incidente no plano do coletor em média diária e da diferença entre a temperatura média ambiente e a de carga, possibilitando o cálculo da Produção Mensal de Energia do coletor solar e a comparação da capacidade de geração de energia entre os diferentes modelos."}, {"c": "dou-paragraph", "t": "3.17 Eficiência térmica diária"}, {"c": "dou-paragraph", "t": "Medida adimensional calculada para os sistemas acoplados que representa, no dia padrão, a relação entre a quantidade de energia útil diária gerada, obtida experimentalmente, por unidade de área bruta do coletor acoplado e a radiação solar global incidente no plano do coletor, em média diária."}, {"c": "dou-paragraph", "t": "3.18 Eficiência térmica média"}, {"c": "dou-paragraph", "t": "Medida adimensional calculada para os coletores solares que representa, no dia padrão, o valor da eficiência térmica do modelo quando é atingido o ponto médio da curva de eficiência térmica, obtida experimentalmente."}, {"c": "dou-paragraph", "t": "3.19 Estagnação"}, {"c": "dou-paragraph", "t": "Condição de um coletor ou sistema quando o calor não está sendo removido pelo fluido de transferência de calor."}, {"c": "dou-paragraph", "t": "3.20 Grau de Proteção IP24"}, {"c": "dou-paragraph", "t": "Grau de proteção de invólucros de equipamentos elétricos, em que o invólucro prevê o impedimento do acesso dos dedos às partes perigosas, a proteção contra corpos com diâmetro maior ou igual a 12,5 mm e a proteção contra aspersão de água em todas as direções."}, {"c": "dou-paragraph", "t": "3.21 Isolação básica"}, {"c": "dou-paragraph", "t": "Isolação aplicada às partes vivas para assegurar o mínimo de proteção contra choque elétrico."}, {"c": "dou-paragraph", "t": "3.22 Parte viva"}, {"c": "dou-paragraph", "t": "Qualquer condutor ou parte condutora projetada para ser energizada em utilização normal, incluindo o condutor neutro, mas, por convenção, não um condutor neutro de proteção aterrado."}, {"c": "dou-paragraph", "t": "3.23 Perda específica de energia mensal"}, {"c": "dou-paragraph", "t": "Medida calculada para os reservatórios termossolares que representa a relação entre a energia dissipada para o ambiente em um mês e a capacidade volumétrica do reservatório, em kWh/l.mês."}, {"c": "dou-paragraph", "t": "3.24 Pressão máxima de trabalho"}, {"c": "dou-paragraph", "t": "Maior valor da pressão de água compatível com o código de projeto, a resistência dos materiais utilizados, as dimensões do equipamento e seus parâmetros operacionais."}, {"c": "dou-paragraph", "t": "3.25 Produção mensal de energia ( P men)"}, {"c": "dou-paragraph", "t": "Quantidade de energia gerada por mês pelos coletores solares ou sistemas acoplados, em kWh/mês."}, {"c": "dou-paragraph", "t": "3.26 Produção mensal específica de energia (PMEe)"}, {"c": "dou-paragraph", "t": "Relação entre a Produção Mensal de Energia ( P men) do coletor solar ou do sistema acoplado e a área bruta (AG) do coletor, em kWh/mês.m 2 . Corresponde à capacidade do objeto para a geração de energia, considerando sua operação no dia padrão."}, {"c": "dou-paragraph", "t": "3.27 Reservatório termossolar"}, {"c": "dou-paragraph", "t": "Recipiente para acumular a energia térmica na forma de água quente, com opção de dispositivos elétricos incorporados para controlar a temperatura da água, que possui pontos específicos de entrada e saída para integração com o coletor solar."}, {"c": "dou-paragraph", "t": "Nota: São considerados partes do reservatório termossolar: fluido de trabalho, tanque, isolamento térmico e, desde que internos ao próprio reservatório termossolar, dispositivos como trocadores de calor sistema de controle de escoamento (válvulas chicanas) e sistema de aquecimento auxiliar."}, {"c": "dou-paragraph", "t": "3.28 Reservatório termossolar aberto"}, {"c": "dou-paragraph", "t": "Reservatório térmico não hermético cuja água armazenada tem contato direto com o ar atmosférico, possuindo boia de controle de nível interno e tampa de acesso na parte superior."}, {"c": "dou-paragraph", "t": "3.29 Reservatório termossolar fechado de alta pressão"}, {"c": "dou-paragraph", "t": "Recipiente de armazenamento de água, fechado para a atmosfera, concebido para funcionar sob a pressão do sistema, limitado por uma válvula de alívio de pressão e temperatura, que possui entrada e saída para a interligação com o coletor solar."}, {"c": "dou-paragraph", "t": "3.30 Reservatório termossolar fechado de baixa pressão"}, {"c": "dou-paragraph", "t": "Recipiente de armazenamento de água, aberto para a atmosfera por meio de um respiro instalado no reservatório ou na saída do consumo, sem válvulas, que possui entrada e saída para interligação com o coletor solar."}, {"c": "dou-paragraph", "t": "3.31 Reservatório termossolar fechado de nível"}, {"c": "dou-paragraph", "t": "Reservatório termossolar cujo enchimento é controlado por uma caixa d'agua instalada em nível, dotado de mecanismo para distribuir água mesmo com reservatório parcialmente cheio e respiro."}, {"c": "dou-paragraph", "t": "3.32 Tanque auxiliar de abastecimento (caixa de quebra pressão)"}, {"c": "dou-paragraph", "t": "Dispositivo utilizado para quebrar a pressão de entrada no reservatório da água da rede de abastecimento, também conhecido como caixa de quebra pressão."}, {"c": "dou-paragraph", "t": "Nota: A capacidade do tanque não é considerada na determinação do volume útil ou nominal do reservatório."}, {"c": "dou-paragraph", "t": "3.33 Temperatura de estagnação"}, {"c": "dou-paragraph", "t": "Temperatura atingida no absorvedor do coletor quando o calor não está sendo removido pelo fluido de transferência de calor."}, {"c": "dou-paragraph", "t": "3.34 Sistema acoplado"}, {"c": "dou-paragraph", "t": "Conjunto do coletor solar com o reservatório termossolar, podendo ser de dois tipos, justaposto ou monobloco."}, {"c": "dou-paragraph", "t": "3.35 Sistema acoplado justaposto"}, {"c": "dou-paragraph", "t": "Sistema acoplado em que o coletor solar e o reservatório termossolar não formam um corpo único, estando fisicamente dissociados."}, {"c": "dou-paragraph", "t": "3.36 Sistema acoplado monobloco"}, {"c": "dou-paragraph", "t": "Sistema acoplado em que o coletor solar e o reservatório termossolar formam um corpo único, estando fisicamente unidos."}, {"c": "dou-paragraph", "t": "3.37 Volume nominal do reservatório termossolar"}, {"c": "dou-paragraph", "t": "Volume declarado pelo fornecedor."}, {"c": "dou-paragraph", "t": "3.38 Volume do reservatório termossolar"}, {"c": "dou-paragraph", "t": "Volume de fluido de trabalho no interior do reservatório termossolar."}, {"c": "dou-paragraph", "t": "3.39 Volume útil armazenado do reservatório termossolar"}, {"c": "dou-paragraph", "t": "Volume de água obtido pelo produto da massa do fluido de trabalho pelo volume específico na temperatura do ensaio."}, {"c": "dou-paragraph", "t": "3.40 Válvula de segurança de pressão"}, {"c": "dou-paragraph", "t": "Dispositivo mecânico atuado por pressão, mantido fechado, projetado para abrir automaticamente e reduzir a pressão quando esta atingir um valor pré-ajustado, podendo apresentar acionamento manual ou mecânico, ou ambos, de abertura, para teste de funcionamento, limpeza ou ensaio."}, {"c": "dou-paragraph", "t": "3.41 Válvula de segurança de temperatura"}, {"c": "dou-paragraph", "t": "Dispositivo de segurança atuado pela temperatura, projetado para abrir automaticamente quando este atingir um valor pré-ajustado."}, {"c": "dou-paragraph", "t": "4. REQUISITOS TÉCNICOS"}, {"c": "dou-paragraph", "t": "4.1 Requisitos para coletores"}, {"c": "dou-paragraph", "t": "4.1.1 O desempenho térmico do coletor deve ser medido e declarado pelo fornecedor."}, {"c": "dou-paragraph", "t": "4.1.2 O coletor deve suportar a elevação de pressão máxima especificada pelo fornecedor, inclusive em condições de alta temperatura possíveis durante suas operações ao longo de sua vida útil."}, {"c": "dou-paragraph", "t": "4.1.3 A pressão de trabalho mínima dos dutos ou tubos do coletor deve ser maior ou igual a 5 m.c.a."}, {"c": "dou-paragraph", "t": "4.1.4 O coletor deve suportar altos níveis de radiação sem falhas, como ruptura do vidro, comprometimento dos vedantes, colapso da cobertura de plástico ou do absorvedor de plástico fundido, ou de ambos."}, {"c": "dou-paragraph", "t": "4.1.5 O coletor não pode apresentar dano ou degradação que altere de forma significativa seu desempenho, nas condições diversas possíveis durante suas operações ao longo de sua vida útil."}, {"c": "dou-paragraph", "t": "4.1.7 A caixa externa do coletor não pode permitir o acúmulo de água da chuva que comprometa a sua capacidade funcional e durabilidade."}, {"c": "dou-paragraph", "t": "4.1.8 A cobertura transparente do coletor fechado e a caixa do aparelho, bem como as fixações entre essas partes, devem ser capazes de resistir às cargas de pressão positiva e negativa devido ao efeito do vento de, no mínimo, 1000 Pa."}, {"c": "dou-paragraph", "t": "4.1.9 O coletor deve suportar o congelamento e ciclos de congelamento e degelo, sempre que declarado pelo fornecedor que é resistente a tais processos."}, {"c": "dou-paragraph", "t": "4.1.10 O coletor deve possuir materiais e componentes resistentes aos impactos provocados por chuva de granizo, sempre que declarado pelo fornecedor que é resistente a tais impactos."}, {"c": "dou-paragraph", "t": "4.1.11 Os materiais poliméricos do coletor, expostos à radiação solar durante suas operações ao longo de sua vida útil, devem ser resistentes à degradação."}, {"c": "dou-paragraph", "t": "4.1.12 O coletor deve ser projetado e fabricado de modo a evitar riscos que afetem sua segurança, eficiência térmica ou vida útil, tais como:"}, {"c": "dou-paragraph", "t": "a) vazamentos;"}, {"c": "dou-paragraph", "t": "b) deformações (expansões, contrações ou distorções);"}, {"c": "dou-paragraph", "t": "c) degradações;"}, {"c": "dou-paragraph", "t": "d) emanação de gases;"}, {"c": "dou-paragraph", "t": "e) deformação permanente de componentes;"}, {"c": "dou-paragraph", "t": "f) sinais de entrada de água e manchas na face interna do vidro;"}, {"c": "dou-paragraph", "t": "g) trincas, empenamento, corrosão;"}, {"c": "dou-paragraph", "t": "h) perda de rigidez ou segurança da estrutura;"}, {"c": "dou-paragraph", "t": "i) perda de aderência e elasticidade da vedação;"}, {"c": "dou-paragraph", "t": "j) perda de contato entre tubo e absorvedor;"}, {"c": "dou-paragraph", "t": "k) fissuras, empenamento, desgaste ou abaulamento da cobertura ou refletor;"}, {"c": "dou-paragraph", "t": "l) destruição da cobertura e danos em partes específicas;"}, {"c": "dou-paragraph", "t": "m) danos que interfiram na transmissão da radiação através da cobertura;"}, {"c": "dou-paragraph", "t": "n) degradação da pintura ou material do absorvedor; e"}, {"c": "dou-paragraph", "t": "o) qualquer dano que resulte em redução da eficiência térmica ou da vida útil."}, {"c": "dou-paragraph", "t": "4.1.13 As seguintes características dos coletores devem ser calculadas e informadas:"}, {"c": "dou-paragraph", "t": "a) Produção Mensal Específica de Energia (PMEe) do coletor (kWh/mês.m 2 );"}, {"c": "dou-paragraph", "t": "b) Produção Mensal de Energia (Pmen) por coletor ou módulo (kWh/mês);"}, {"c": "dou-paragraph", "t": "c) Eficiência térmica média do coletor;"}, {"c": "dou-paragraph", "t": "d) Área bruta (AG) do coletor (m 2 ); e"}, {"c": "dou-paragraph", "t": "e) Pressão de funcionamento (kPa)."}, {"c": "dou-paragraph", "t": "4.1.14 A PMEe do coletor deve ser classificada quanto a sua eficiência energética e atender aos níveis mínimos de 52,3 kWh/mês.m 2 para aplicação banho e de 65,0 kWh/mês.m 2 para aplicação piscina."}, {"c": "dou-paragraph", "t": "4.1.15 O coletor, quando fabricado de materiais poliméricos reciclados, não pode conter substâncias químicas tóxicas que possam migrar para a água e representar risco à saúde humana."}, {"c": "dou-paragraph", "t": "4.2 Requisitos para reservatórios"}, {"c": "dou-paragraph", "t": "4.2.1 O reservatório deve possuir variação máxima entre o volume útil e o volume nominal de - 5% a 10%."}, {"c": "dou-paragraph", "t": "4.2.2 O reservatório não pode apresentar vazamento ou deformação permanente visível mesmo sob condições extremas de pressão hidrostática possíveis durante suas operações ao longo de sua vida útil."}, {"c": "dou-paragraph", "t": "4.2.3 O reservatório deve apresentar valores máximos de Perda Específica de Energia Mensal, por capacidade, conforme Tabela 1."}, {"c": "dou-paragraph", "t": "Tabela 1 - Perda específica de energia mensal máxima do reservatório termossolar por capacidade"}, {"c": "", "t": "Volume nominal doreservatório termossolar (l)"}, {"c": "", "t": "Perda Específica de EnergiaMensal Máxima (kWh/l.mês)"}, {"c": "", "t": "100"}, {"c": "", "t": "<0,27"}, {"c": "", "t": "150"}, {"c": "", "t": "<0,27"}, {"c": "", "t": "200"}, {"c": "", "t": "<0,27"}, {"c": "", "t": "250"}, {"c": "", "t": "<0,27"}, {"c": "", "t": "300"}, {"c": "", "t": "<0,27"}, {"c": "", "t": "400"}, {"c": "", "t": "<0,22"}, {"c": "", "t": "500"}, {"c": "", "t": "<0,21"}, {"c": "", "t": "600"}, {"c": "", "t": "<0,20"}, {"c": "", "t": "800"}, {"c": "", "t": "<0,18"}, {"c": "", "t": ">1000"}, {"c": "", "t": "<0,16"}, {"c": "dou-paragraph", "t": "4.2.4 O reservatório deve possuir e assegurar a isolação e continuidade elétrica entre o condutor (fio terra ou cabo elétrico) e os invólucros metálicos interno e externo, mesmo sob condições extremas de tensão possíveis durante suas operações ao longo de sua vida útil."}, {"c": "dou-paragraph", "t": "4.2.5 A corrente de fuga do reservatório não pode exceder o limite máximo 5 mA."}, {"c": "dou-paragraph", "t": "4.2.6 O reservatório deve possuir variação máxima entre a potência elétrica absorvida de -10% a 5% do valor declarado pelo fornecedor."}, {"c": "dou-paragraph", "t": "4.2.7 As partes de material isolante, de isolante suplementar ou reforçado e as partes externas não metálicas do reservatório não podem sofrer deterioração que prejudiquem sua segurança elétrica e contra incêndio."}, {"c": "dou-paragraph", "t": "4.2.8 As partes ferrosas do reservatório devem apresentar resistência à oxidação, mesmo sob condições ambientais extremas possíveis durante suas operações ao longo de sua vida útil."}, {"c": "dou-paragraph", "t": "4.2.9 Os materiais poliméricos do reservatório, expostos à radiação solar durante suas operações ao longo de sua vida útil, devem ser resistentes à degradação."}, {"c": "dou-paragraph", "t": "4.2.10 O reservatório deve apresentar grau de proteção IP24."}, {"c": "dou-paragraph", "t": "4.2.11 O reservatório, quando fabricado de material polimérico reciclado, não pode conter substâncias químicas tóxicas que possam migrar para a água e representar risco à saúde humana."}, {"c": "dou-paragraph", "t": "4.2.12 A capacidade do reservatório deve ser padronizada em 100 l, 150 l, 200 l, 250 l, 300 l, 400 l, 500 l, 600 l, 800 l ou 1000 l."}, {"c": "dou-paragraph", "t": "4.3 Requisitos para sistemas acoplados"}, {"c": "dou-paragraph", "t": "4.3.1 O coletor do sistema acoplado deve atender a todos os requisitos do subitem 4.1 deste RTQ, exceto o subitem 4.1.9."}, {"c": "dou-paragraph", "t": "4.3.2 O reservatório do sistema acoplado deve atender a todos os requisitos do subitem 4.2 deste RTQ, exceto o subitem 4.2.12."}, {"c": "dou-paragraph", "t": "4.3.4 A PMEe do sistema acoplado deve ser classificada quanto a sua eficiência energética e atender ao nível mínimo de 52,3 kWh/mês.m 2 para aplicação banho."}, {"c": "dou-paragraph", "t": "5. REQUISITOS DE MARCAÇÕES E INFORMAÇÕES OBRIGATÓRIAS NO PRODUTO OU EMBALAGEM"}, {"c": "dou-paragraph", "t": "5.1 Os equipamentos disponibilizados no mercado nacional devem apresentar marcações e informações claras e em língua portuguesa, que permitam sua rastreabilidade."}, {"c": "dou-paragraph", "t": "5.2 As marcações devem ser apostas de forma permanente no produto ou embalagem, podendo ser por impressão, clichê ou colagem, com as seguintes informações mínimas:"}, {"c": "dou-paragraph", "t": "a) Nome ou razão social e identificação fiscal (CNPJ) do fornecedor;"}, {"c": "dou-paragraph", "t": "b) Selo de Identificação da Conformidade (ENCE);"}, {"c": "dou-paragraph", "t": "c) Designação comercial do produto (modelo e código);"}, {"c": "dou-paragraph", "t": "d) Data de fabricação (dia, mês e ano, nesta ordem);"}, {"c": "dou-paragraph", "t": "e) Identificação do número de série, lote ou outra marcação que permita a rastreabilidade do produto; e"}, {"c": "dou-paragraph", "t": "f) País de origem, não sendo aceitas designações através de blocos econômicos, nem indicações por bandeiras de países."}, {"c": "dou-paragraph", "t": "5.3 O coletor deve conter em seu corpo as seguintes marcações:"}, {"c": "dou-paragraph", "t": "a)Produção Mensal Específica de Energia (PMEe) do coletor (kWh/mês.m 2 );"}, {"c": "dou-paragraph", "t": "b)Produção Mensal de Energia (Pmen) por coletor ou módulo (kWh/mês);"}, {"c": "dou-paragraph", "t": "c)Eficiência térmica média do coletor;"}, {"c": "dou-paragraph", "t": "d)Área bruta (AG) do coletor (m 2 ); e"}, {"c": "dou-paragraph", "t": "e)Pressão de funcionamento (kPa)."}, {"c": "dou-paragraph", "t": "5.4 O reservatório deve conter em seu corpo marcações de advertência para reduzir os perigos previsíveis relacionados a seu uso, conforme indicado na Tabela 2."}, {"c": "dou-paragraph", "t": "Tabela 2 - Marcações de advertência em reservatórios"}, {"c": "", "t": "Marcações"}, {"c": "", "t": "Posicionamento de aposição"}, {"c": "", "t": "\" ATENÇÃO: antes de acessar os terminais elétricos, todos os circuitos alimentadores devem ser desligados\"."}, {"c": "", "t": "Essa advertência deve ser localizada próxima da tampa dos terminais."}, {"c": "", "t": "\"IMPORTANTE PARA SUA SEGURANÇA: para evitar riscos de choques elétricos, este Fio Terra deve ser conectado a um sistema de aterramento\"."}, {"c": "", "t": "Essa advertência deve estar disposta em uma etiqueta removível a ser fixada ao terminal ou Fio Terra do aparelho e que deve estar disponível no momento da instalação."}, {"c": "", "t": "\"IMPORTANTE PARA SUA SEGURANÇA: este reservatório deverá ser provido de dispositivo de alívio de pressão\"."}, {"c": "", "t": "Essa advertência deve ser localizada na superfície do reservatório, em lugar visível ao usuário."}, {"c": "dou-paragraph", "t": "5.4.1 O reservatório deve conter marcações duráveis, claramente discerníveis, visíveis no momento da sua instalação e aplicadas sobre parte não destacável."}, {"c": "dou-paragraph", "t": "5.4.2 Os terminais de conexão da alimentação elétrica do reservatório devem ser marcados de forma a diferenciar aqueles destinados exclusivamente ao condutor de neutro daqueles de aterramento."}, {"c": "dou-paragraph", "t": "5.4.2.1 Os terminais destinados exclusivamente ao condutor de neutro devem ser indicados pela letra N."}, {"c": "dou-paragraph", "t": "5.4.2.2 Os terminais de aterramento devem ser indicados pelo símbolo de aterramento."}, {"c": "dou-paragraph", "t": "5.4.3 Caso um dispositivo de proteção unifilar seja inserido no circuito do condutor de fase no interior de aparelhos classe 0I ou I monofásicos, destinados à ligação permanente à fiação, o terminal correspondente deve ser claramente indicado."}, {"c": "dou-paragraph", "t": "5.4.4 O reservatório fornecido com cordão de alimentação deve ter a identificação através da cor da isolação dos condutores, sendo verde ou verde/amarelo para o fio terra e azul claro para fio neutro."}, {"c": "dou-paragraph", "t": "5.4.5 A entrada e a saída de água ao consumo da rede de alimentação devem ser identificadas, e quando utilizadas cores, deve ser utilizado azul para a entrada e vermelho para a saída."}, {"c": "dou-paragraph", "t": "ANEXO II REQUISITOS DE AVALIAÇÃO DA CONFORMIDADE PARA EQUIPAMENTOS DE AQUECIMENTO SOLAR DE ÁGUA"}, {"c": "dou-paragraph", "t": "1. OBJETIVO"}, {"c": "dou-paragraph", "t": "Estabelecer critérios e procedimentos de avaliação da conformidade para equipamentos de aquecimento solar de água, com foco na segurança e no desempenho, por meio do mecanismo de certificação, visando à prevenção de acidentes e à eficiência energética."}, {"c": "dou-paragraph", "t": "Nota 1: Neste RAC, os \"equipamentos de aquecimento solar de água\" são denominados \"equipamentos\", os \"coletores solares\" são denominados \"coletores\" e os \"reservatórios termossolares\" são denominados \"reservatórios\"."}, {"c": "dou-paragraph", "t": "Nota 2: Os requisitos de avaliação da conformidade específicos para cada tipo de equipamento estão estabelecidos no Anexo Específico A (Coletores Solares), Anexo Específico B (Reservatórios Termossolares) e Anexo Específico C (Sistemas Acoplados)."}, {"c": "dou-paragraph", "t": "1.1 Agrupamento para efeito de certificação"}, {"c": "dou-paragraph", "t": "1.1.1 Para a certificação de coletores e reservatórios, aplica-se o conceito de família, conforme as definições estabelecidas, respectivamente, nos subitens 4.1 e 4.2 deste RAC."}, {"c": "dou-paragraph", "t": "1.1.2 Para a certificação de sistemas acoplados, aplica-se o conceito de modelo, conforme a definição estabelecida no subitem 4.4 deste RAC."}, {"c": "dou-paragraph", "t": "3. DOCUMENTOS COMPLEMENTARES"}, {"c": "dou-paragraph", "t": "Para fins deste RAC, são adotados os documentos complementares listados no RGCP, além dos citados a seguir e nos Anexos Específicos deste RAC:"}, {"c": "", "t": "Portaria Inmetro nº 200, de 2021"}, {"c": "", "t": "Aprova os Requisitos Gerais de Certificação de Produtos - RGCP"}, {"c": "", "t": "ISO 9488:2022"}, {"c": "", "t": "Solar energy - Vocabulary"}, {"c": "dou-paragraph", "t": "4. DEFINIÇÕES"}, {"c": "dou-paragraph", "t": "Para fins deste RAC, são adotadas as definições a seguir, complementadas pelas constantes nos documentos complementares citados no item 3, nos Anexos Específicos deste RAC e no RTQ."}, {"c": "dou-paragraph", "t": "4.1 Família de coletor solar"}, {"c": "dou-paragraph", "t": "Agrupamento de modelos de coletor solar, em torno de um mesmo modelo base, provenientes de uma mesma unidade produtiva e que possuem a mesma aplicação (banho ou piscina)."}, {"c": "dou-paragraph", "t": "Nota: Coletores com tipos diferentes de vidros (liso comum ou temperado/termo endurecido) podem compor uma mesma família."}, {"c": "dou-paragraph", "t": "4.2 Família de reservatório termossolar"}, {"c": "dou-paragraph", "t": "Agrupamento dos modelos de reservatório térmico, provenientes de uma mesma unidade produtiva, com a mesma pressão de trabalho, mesmos diâmetros interno e externo do reservatório, mesmos materiais do cilindro interno e isolamento térmico do reservatório, mesmo fluido de trabalho e mesma potência elétrica. Podem variar, na mesma família, a existência de resistência elétrica (sim ou não), a orientação (vertical ou horizontal), a existência de anodo de sacrifício (sim ou não), a quantidade e as bitolas dos tubos, e materiais do revestimento externo (chapa de alumínio e suas ligas, galvalume, chapa de aço inoxidável e suas ligas)."}, {"c": "dou-paragraph", "t": "4.3 Modelo base de coletor solar"}, {"c": "dou-paragraph", "t": "Modelo representativo da família de coletores solares, apresentando o mesmo desempenho térmico, mesma espessura do vidro (com tolerância de ± 10%) e mesmo coeficiente de transmitância do vidro, sendo admitidas alterações do tipo de vidro (liso comum ou temperado/termo endurecido) e alterações dimensionais (extensões horizontal, vertical, por rebatimento ou diâmetro da calha coletora)."}, {"c": "dou-paragraph", "t": "Nota 1: A extensão horizontal consiste no aumento da dimensão externa horizontal do coletor (perpendicular aos tubos absorvedores) em relação ao modelo base da família, podendo apresentar valores diversos, mas limitados ao dobro da dimensão do modelo base, e mantidas todas as demais especificações técnicas. A relação entre a dimensão externa horizontal do modelo base e o número de tubos do coletor deve manter-se na extensão horizontal, respeitando a distância entre tubos e o comprimento das aletas, de modo que ( X base /N base ) = (X extensão /N extensão )."}, {"c": "dou-paragraph", "t": "Nota 2: A extensão vertical consiste no aumento da dimensão externa vertical (paralela aos tubos absorvedores) do coletor em relação ao modelo base da família, podendo apresentar valores diversos, mas mantidos o número de tubos e todas as demais especificações técnicas."}, {"c": "dou-paragraph", "t": "Nota 3: A extensão por rebatimento consiste na inversão das medidas das dimensões externas horizontal (perpendicular aos tubos absorvedores) e vertical (paralela aos tubos absorvedores) do modelo base de coletor solar, ocasionando incremento no número de tubos absorvedores e redução do seu comprimento."}, {"c": "dou-paragraph", "t": "Nota 4: A extensão por diâmetro da calha coletora consiste na diferenciação do coletor solar quanto ao diâmetro das calhas coletoras. Esse parâmetro é modificado para um valor maior ou menor que o do modelo base de coletor solar."}, {"c": "dou-paragraph", "t": "4.4 Modelo de sistema acoplado"}, {"c": "dou-paragraph", "t": "Versões de sistema acoplado, provenientes de uma mesma unidade produtiva, que possuem a mesma aplicação (banho ou piscina) e que não apresentam diferença em suas características construtivas e dimensionais."}, {"c": "dou-paragraph", "t": "4.5 Planilha de Especificações Técnicas (PET)"}, {"c": "dou-paragraph", "t": "Memorial descritivo com informações referentes aos modelos integrantes da família de produtos, conforme os modelos estabelecidos nos Anexos \"A\" dos Anexos Específicos deste RAC."}, {"c": "dou-paragraph", "t": "5. MECANISMO DE AVALIAÇÃO DA CONFORMIDADE"}, {"c": "dou-paragraph", "t": "O mecanismo de avaliação da conformidade para os equipamentos de aquecimento solar de água é a certificação."}, {"c": "dou-paragraph", "t": "6. ETAPAS DA AVALIAÇÃO DA CONFORMIDADE"}, {"c": "dou-paragraph", "t": "6.1 Definição dos Modelos de Certificação Utilizados"}, {"c": "dou-paragraph", "t": "Este RAC estabelece 2 modelos de certificação distintos, cabendo ao fornecedor optar por um deles:"}, {"c": "dou-paragraph", "t": "a) Modelo de Certificação 4: avaliação inicial consistindo de ensaios em amostras retiradas no fabricante seguida de avaliação de manutenção periódica através de coleta de amostra do produto na fábrica e no comércio, combinados."}, {"c": "dou-paragraph", "t": "b) Modelo de Certificação 5: avaliação inicial consistindo de ensaios em amostras retiradas no fabricante, incluindo auditoria do Sistema de Gestão da Qualidade (SGQ), seguida de avaliação de manutenção periódica através de coleta de amostra do produto na fábrica e no comércio, para realização das atividades de avaliação da conformidade, e auditoria do SGQ."}, {"c": "dou-paragraph", "t": "6.2 Modelo de Certificação 5"}, {"c": "dou-paragraph", "t": "6.2.1 Avaliação Inicial"}, {"c": "dou-paragraph", "t": "6.2.1.1 Solicitação de Certificação"}, {"c": "dou-paragraph", "t": "O fornecedor deve encaminhar uma solicitação formal ao OCP, fornecendo a documentação descrita no RGCP, além dos seguintes itens:"}, {"c": "dou-paragraph", "t": "a) PET de cada família (coletor ou reservatório) ou modelo (sistema acoplado) de produto a ser certificado, conforme os modelos apresentados nos Anexos Específicos deste RAC; e"}, {"c": "dou-paragraph", "t": "b) manual de instruções de cada modelo da família, contendo informações sobre uso e manutenção."}, {"c": "dou-paragraph", "t": "6.2.1.2 Análise da Solicitação e da Conformidade da Documentação"}, {"c": "dou-paragraph", "t": "Os critérios de análise da solicitação e da conformidade da documentação devem seguir os requisitos descritos no RGCP."}, {"c": "dou-paragraph", "t": "6.2.1.3 Auditoria Inicial do Sistema de Gestão da Qualidade e Avaliação do Processo Produtivo"}, {"c": "dou-paragraph", "t": "Os critérios de auditoria inicial do sistema de gestão devem seguir os requisitos estabelecidos no RGCP."}, {"c": "dou-paragraph", "t": "6.2.1.4 Plano de Ensaios Iniciais"}, {"c": "dou-paragraph", "t": "Os critérios do plano de ensaios iniciais devem seguir os requisitos estabelecidos no RGCP."}, {"c": "dou-paragraph", "t": "6.2.1.4.1 Definição dos Ensaios a Serem Realizados"}, {"c": "dou-paragraph", "t": "6.2.1.4.1.1 Os critérios para a definição dos ensaios a serem realizados devem seguir os requisitos descritos no RGCP."}, {"c": "dou-paragraph", "t": "6.2.1.4.1.12Os ensaios, seus métodos e critérios de aceitação/rejeição estão definidos nos Anexos Específicos deste RAC."}, {"c": "dou-paragraph", "t": "6.2.1.4.1.3 Para a certificação dos equipamentos, todos os ensaios e inspeções definidos nos Anexos Específicos deste RAC devem ser realizados, exceto quando estabelecida exclusão ou regra diferenciada neste RAC."}, {"c": "dou-paragraph", "t": "6.2.1.4.1.4 Além dos ensaios da avaliação inicial, os equipamentos devem ser inspecionados, por meio da verificação visual e medições, com a finalidade de confirmar as informações declaradas na PET."}, {"c": "dou-paragraph", "t": "6.2.1.4.1.5 Quando não for possível verificar a conformidade de alguma característica do coletor antes da realização dos ensaios, a evidência da conformidade pode ser verificada após os ensaios, quando o equipamento pode ser desmontado."}, {"c": "dou-paragraph", "t": "6.2.1.4.2 Definição da Amostragem"}, {"c": "dou-paragraph", "t": "6.2.1.4.2.1 Os critérios para a definição da amostragem devem seguir os requisitos descritos no RGCP e nos Anexos Específicos deste RAC."}, {"c": "dou-paragraph", "t": "6.2.1.4.2.2 O OCP é responsável pela coleta das amostras do equipamento a ser certificado, por família (coletor ou reservatório) ou modelo (sistema acoplado)."}, {"c": "dou-paragraph", "t": "6.2.1.4.2.3 A coleta da amostra realizada nas dependências do fabricante deve ser aleatória, realizada pelo OCP, em lotes de fabricação já inspecionados e liberados pelo controle de qualidade da fábrica, na área de estoque de produto acabado, em embalagem pronta para a comercialização."}, {"c": "dou-paragraph", "t": "6.2.1.4.2.4 Se os ensaios forem realizados em protótipos, deve ser considerado o subitem 6.2.3.7 do RGCP."}, {"c": "dou-paragraph", "t": "6.2.1.4.3 Definição do Laboratório"}, {"c": "dou-paragraph", "t": "Os critérios para a definição de laboratório devem seguir os requisitos estabelecidos no RGCP."}, {"c": "dou-paragraph", "t": "6.2.1.5 Tratamento de Não Conformidades na Etapa de Avaliação Inicial"}, {"c": "dou-paragraph", "t": "Os critérios para tratamento de não conformidades na etapa de avaliação inicial devem seguir os requisitos estabelecidos no RGCP."}, {"c": "dou-paragraph", "t": "6.2.1.6 Emissão do Certificado de Conformidade"}, {"c": "dou-paragraph", "t": "6.2.1.6.1 Os critérios para emissão do Certificado de Conformidade devem seguir os requisitos estabelecidos no RGCP."}, {"c": "dou-paragraph", "t": "6.2.1.6.2 O certificado tem validade de 6 (seis) anos, contados a partir da data de emissão."}, {"c": "dou-paragraph", "t": "6.2.1.6.3 Além da documentação descrita no RGCP, deve ser anexado ao certificado a PET referente à família (coletor e reservatório) ou modelo (sistema acoplado) do produto certificado, devidamente ratificada pelo OCP."}, {"c": "dou-paragraph", "t": "6.2.1.6.4 No certificado, o(s) modelo(s) deve(m) ser notado(s) da seguinte forma:"}, {"c": "dou-paragraph", "t": "Quadro 1 - Notação do(s) modelo(s) da família no certificado - Coletor Solares"}, {"c": "", "t": "Marca"}, {"c": "", "t": "Modelo (Designação Comercial do Modelo e código(s) de referência comercial(is)) de todas as versões, se existentes"}, {"c": "", "t": "Descrição (Descrição Técnica do Modelo)- Pressão de funcionamento (kPa)- Tipo do vidro (mm)- Dimensões (largura x comprimento x altura) (mm)- Área bruta (m 2 )"}, {"c": "", "t": "Código de barras comercial (quando existente) de todas as versões"}, {"c": "dou-paragraph", "t": "Quadro 2 - Notação do(s) modelo(s) da família no certificado - Reservatórios Termossolares"}, {"c": "", "t": "Marca"}, {"c": "", "t": "Modelo (Designação Comercial do Modelo e código(s) de referência comercial(is)) de todas as versões, se existentes"}, {"c": "", "t": "Descrição (Descrição Técnica do Modelo)- Volume nominal- Dimensões Externas (comprimento) (mm)- Orientação (vertical ou horizontal)- Materiais do revestimento externo (chapa de alumínio e suas ligas, galvalume, chapa de aço inoxidável e suas ligas)"}, {"c": "", "t": "Código de barras comercial (quando existente) de todas as versões"}, {"c": "", "t": "- Resistência elétrica (sim ou não)- Existência de anodo de sacrifício (sim ou não)- Quantidade e as bitolas dos tubos"}, {"c": "dou-paragraph", "t": "Quadro 3 - Notação do modelo no certificado - Sistemas Acoplados"}, {"c": "", "t": "Marca"}, {"c": "", "t": "Modelo (Designação Comercial do Modelo e código(s) de referência comercial(is)) de todas as versões, se existentes."}, {"c": "", "t": "Descrição (Descrição Técnica do Modelo)Coletor Solar acoplado:- Aplicação (banho ou piscina)- Espessura do vidro (mm)- Coeficiente de transmitância do vidro"}, {"c": "", "t": "Código de barras comercial (quando existente) de todas as versões"}, {"c": "", "t": "- Tipo de vidro (liso comum ou temperado/termo endurecido)- Pressão de funcionamento (kPa)- Tipo do vidro (mm)- Dimensões (largura x comprimento x altura) (mm)- Área bruta (m 2 )- Material da superfície absorvedora"}, {"c": "", "t": "- Quantidade de tubos- Tecnologia do tuboReservatório termossolar acoplado:- Pressão de funcionamento (kPa)- Volume nominal"}, {"c": "", "t": "- Diâmetros externo e interno, comprimento (mm)- Orientação (vertical ou horizontal)- Materiais do revestimento externo (chapa de alumínio e suas ligas, galvalume, chapa de aço inoxidável e suas ligas)- Materiais do cilindro interno"}, {"c": "", "t": "- Materiais do isolamento térmico- Fluido de trabalho- Resistência elétrica (sim ou não)- Existência de anodo de sacrifício (sim ou não)- Quantidade e as bitolas dos tubos"}, {"c": "dou-paragraph", "t": "6.2.2 Avaliação de Manutenção"}, {"c": "dou-paragraph", "t": "Depois da concessão do Certificado de Conformidade, o acompanhamento da Certificação é realizado pelo OCP para constatar se as condições técnico-organizacionais que deram origem à concessão inicial da certificação continuam sendo cumpridas."}, {"c": "dou-paragraph", "t": "6.2.2.1 Auditoria de Manutenção do Sistema de Gestão da Qualidade e Avaliação do Processo Produtivo"}, {"c": "dou-paragraph", "t": "O OCP deve realizar uma auditoria de manutenção em até 36 (trinta e seis) meses após a concessão do Certificado de Conformidade, conforme os requisitos estabelecidos no RGCP."}, {"c": "dou-paragraph", "t": "6.2.2.2 Plano de Ensaios de Manutenção"}, {"c": "dou-paragraph", "t": "Os critérios para o plano de ensaios de manutenção devem seguir os requisitos estabelecidos no RGCP."}, {"c": "dou-paragraph", "t": "Os ensaios devem ser realizados em até 36 (trinta e seis) meses após a concessão do certificado, para comprovar a manutenção da conformidade dos equipamentos com os requisitos deste RAC."}, {"c": "dou-paragraph", "t": "6.2.2.2.1 Definição dos Ensaios a Serem Realizados"}, {"c": "dou-paragraph", "t": "6.2.2.2.1.1 Antes da realização dos ensaios de manutenção, os equipamentos devem ser inspecionados, conforme estabelecido no subitem 6.2.1.4.1 deste RAC."}, {"c": "dou-paragraph", "t": "6.2.2.2.1.2 Os ensaios, seus métodos e critérios de aceitação/rejeição estão definidos nos Anexos Específicos deste RAC."}, {"c": "dou-paragraph", "t": "6.2.2.2.1.3 O OCP irá definir o(s) equipamento(s) que será(ão) efetivamente ensaiado(s), alternando os ensaios entre o(s) equipamento(s) escolhido(s), conforme as disposições dos Anexos Específicos deste RAC."}, {"c": "dou-paragraph", "t": "6.2.2.2.1.4 Caso o modelo base de uma família de coletor deixe de ser comercializado pelo fornecedor, o OCP deve identificar o novo modelo base da família."}, {"c": "dou-paragraph", "t": "6.2.2.2.1.5 Caso haja alterações parciais no modelo base de coletor, devem ser realizados ensaios específicos em função das alterações propostas, conforme as disposições dos Anexos Específicos deste RAC."}, {"c": "dou-paragraph", "t": "6.2.2.2.2 Definição da Amostragem de Manutenção"}, {"c": "dou-paragraph", "t": "6.2.2.2.2.1 Os critérios para a definição da amostragem devem seguir os requisitos descritos no RGCP, no subitem 6.2.1.4.2 e nos Anexos Específicos deste RAC."}, {"c": "dou-paragraph", "t": "6.2.2.2.2.2 O OCP deve realizar a coleta das amostras no comércio ou no centro de distribuição e na fábrica."}, {"c": "dou-paragraph", "t": "6.2.2.2.3 Definição do Laboratório"}, {"c": "dou-paragraph", "t": "Os critérios para a definição de laboratório devem seguir os requisitos estabelecidos no RGCP."}, {"c": "dou-paragraph", "t": "6.2.2.3 Tratamento de Não Conformidades na Etapa de Avaliação de Manutenção"}, {"c": "dou-paragraph", "t": "Os critérios para tratamento de não conformidades na etapa de avaliação de manutenção devem seguir os requisitos estabelecidos no RGCP."}, {"c": "dou-paragraph", "t": "6.2.2.4 Confirmação da Manutenção"}, {"c": "dou-paragraph", "t": "Os critérios de confirmação da manutenção devem seguir os requisitos estabelecidos no RGCP."}, {"c": "dou-paragraph", "t": "6.2.3 Avaliação de Recertificação"}, {"c": "dou-paragraph", "t": "6.2.3.1 Os critérios para avaliação de recertificação estão contemplados no RGCP e nos Anexos Específicos deste RAC."}, {"c": "dou-paragraph", "t": "6.2.3.2 A avaliação de recertificação deve ser realizada a cada 6 (seis) anos, devendo ser concluída até a data de validade do certificado."}, {"c": "dou-paragraph", "t": "6.3 Modelo de Certificação 4"}, {"c": "dou-paragraph", "t": "6.3.1 Avaliação Inicial"}, {"c": "dou-paragraph", "t": "6.3.1.1 Solicitação de Certificação"}, {"c": "dou-paragraph", "t": "O fornecedor deve encaminhar uma solicitação formal ao OCP de acordo com os critérios estabelecidos no RGCP e no subitem 6.2.1.1 deste RAC."}, {"c": "dou-paragraph", "t": "6.3.1.2 Análise da Solicitação e da Conformidade da Documentação"}, {"c": "dou-paragraph", "t": "Os critérios de análise da solicitação e da conformidade da documentação devem seguir os requisitos descritos no RGCP e no subitem 6.2.1.2 deste RAC."}, {"c": "dou-paragraph", "t": "6.3.1.3 Plano de Ensaios Iniciais"}, {"c": "dou-paragraph", "t": "Os critérios do plano de ensaios iniciais devem seguir os requisitos estabelecidos no RGCP."}, {"c": "dou-paragraph", "t": "6.3.1.3.1 Definição dos Ensaios a serem realizados"}, {"c": "dou-paragraph", "t": "Os critérios para a definição dos ensaios a serem realizados devem seguir os requisitos descritos no RGCP, no subitem 6.2.1.4.1 e nos Anexos Específicos deste RAC."}, {"c": "dou-paragraph", "t": "6.3.1.3.2 Definição da Amostragem"}, {"c": "dou-paragraph", "t": "Os critérios para a definição da amostragem devem seguir os requisitos descritos no RGCP, no subitem 6.2.1.4.2 e nos Anexos Específicos deste RAC."}, {"c": "dou-paragraph", "t": "6.3.1.3.3 6.3.1.3.3 Definição do Laboratório"}, {"c": "dou-paragraph", "t": "Os critérios para a definição de laboratório devem seguir os requisitos estabelecidos no RGCP."}, {"c": "dou-paragraph", "t": "6.3.1.4 Tratamento de Não Conformidades na Etapa de Avaliação Inicial"}, {"c": "dou-paragraph", "t": "Os critérios para o tratamento de não conformidades na etapa de avaliação inicial devem seguir os requisitos estabelecidos no RGCP."}, {"c": "dou-paragraph", "t": "6.3.1.5 Emissão do Certificado de Conformidade"}, {"c": "dou-paragraph", "t": "6.3.1.5.1 Os critérios para emissão do Certificado de Conformidade devem seguir os requisitos estabelecidos no RGCP, no subitem 6.2.1.6, exceto o subitem 6.2.1.6.2."}, {"c": "dou-paragraph", "t": "6.3.1.5.2 O Certificado da Conformidade tem validade de 4 (quatro) anos."}, {"c": "dou-paragraph", "t": "6.3.2 Avaliação de Manutenção"}, {"c": "dou-paragraph", "t": "6.3.2.1 Os critérios de avaliação de manutenção devem seguir os requisitos descritos no RGCP e no subitem 6.2.2, exceto o subitem 6.2.2.1."}, {"c": "dou-paragraph", "t": "6.3.2.2 Os ensaios devem ser realizados em até 24 (vinte e quatro) meses contados da data de concessão inicial, para comprovar a manutenção da conformidade dos equipamentos com os requisitos deste RAC."}, {"c": "dou-paragraph", "t": "6.3.3 Avaliação de Recertificação"}, {"c": "dou-paragraph", "t": "6.3.3.1 Os critérios para avaliação de recertificação estão contemplados no RGCP e nos Anexos Específicos deste RAC."}, {"c": "dou-paragraph", "t": "6.3.3.2 A avaliação de recertificação deve ser realizada a cada 4 (quatro) anos, devendo ser concluída até a data de validade do certificado."}, {"c": "dou-paragraph", "t": "7. TRATAMENTO DE RECLAMAÇÕES"}, {"c": "dou-paragraph", "t": "Os critérios para tratamento de reclamações devem seguir os requisitos estabelecidos no RGCP."}, {"c": "dou-paragraph", "t": "8. ATIVIDADES EXECUTADAS POR OCP ACREDITADO POR MEMBRO DO MLA DO IAF"}, {"c": "dou-paragraph", "t": "Os critérios para atividades executadas por OCP acreditado por membro do MLA do IAF devem seguir os requisitos estabelecidos no RGCP."}, {"c": "dou-paragraph", "t": "9. TRANSFERÊNCIA DA CERTIFICAÇÃO"}, {"c": "dou-paragraph", "t": "Os critérios para transferência da certificação devem seguir os requisitos estabelecidos no RGCP."}, {"c": "dou-paragraph", "t": "10. ENCERRAMENTO DA CERTIFICAÇÃO"}, {"c": "dou-paragraph", "t": "Os critérios para encerramento da certificação devem seguir os requisitos estabelecidos no RGCP."}, {"c": "dou-paragraph", "t": "11. SELO DE IDENTIFICAÇÃO DA CONFORMIDADE"}, {"c": "dou-paragraph", "t": "Os critérios para o Selo de Identificação da Conformidade devem seguir os requisitos estabelecidos no RGCP e no Anexo III."}, {"c": "dou-paragraph", "t": "12. AUTORIZAÇÃO PARA O USO DO SELO DE IDENTIFICAÇÃO DA CONFORMIDADE"}, {"c": "dou-paragraph", "t": "Os critérios para a autorização do uso do Selo de Identificação da Conformidade devem seguir os requisitos estabelecidos no RGCP."}, {"c": "dou-paragraph", "t": "13. RESPONSABILIDADES E OBRIGAÇÕES"}, {"c": "dou-paragraph", "t": "13.1 Os critérios para responsabilidades e obrigações devem seguir os requisitos estabelecidos no RGCP, além do seguinte."}, {"c": "dou-paragraph", "t": "13.2 13.2 Toda e qualquer modificação ou melhoria, ou ambas, do projeto dos equipamentos objeto deste RAC deve ser declarada pelo fornecedor ao OCP, por meio da atualização das informações declaradas na PET, de modo a garantir que a PET represente com fidelidade as características da família ou modelo certificado, podendo o OCP requisitar novos ensaios."}, {"c": "dou-paragraph", "t": "14. ACOMPANHAMENTO NO MERCADO"}, {"c": "dou-paragraph", "t": "Os critérios para acompanhamento no mercado devem seguir os requisitos estabelecidos no RGCP."}, {"c": "dou-paragraph", "t": "15. PENALIDADES"}, {"c": "dou-paragraph", "t": "Os critérios para aplicação de penalidades devem seguir os requisitos estabelecidos no RGCP."}, {"c": "dou-paragraph", "t": "16. DENÚNCIAS, RECLAMAÇÕES E SUGESTÕES"}, {"c": "dou-paragraph", "t": "Os critérios para aplicação das denúncias devem seguir os requisitos estabelecidos no RGCP."}, {"c": "dou-paragraph", "t": "ANEXO ESPECÍFICO A - COLETORES SOLARES"}, {"c": "dou-paragraph", "t": "1. DOCUMENTOS COMPLEMENTARES"}, {"c": "", "t": "ABNT NBR 17003:2021"}, {"c": "", "t": "Sistemas solares térmicos e seus componentes - Coletores solares - Requisitos gerais e métodos de ensaio"}, {"c": "", "t": "ASTM G155:25"}, {"c": "", "t": "Standard Practice for Operating Xenon Arc Light Apparatus for Exposure of Materials"}, {"c": "", "t": "ISO 9806:2025"}, {"c": "", "t": "Solar energy - Solar thermal collectors - Test methods"}, {"c": "", "t": "ISO 9459-2:1995"}, {"c": "", "t": "Solar heating - Domestic water heating systems - Part 2: Outdoor test methods for system performance characterization and yearly performance prediction of solar-only systems"}, {"c": "dou-paragraph", "t": "2. ENSAIOS"}, {"c": "dou-paragraph", "t": "2.1 Definição dos Ensaios a Serem Realizados"}, {"c": "dou-paragraph", "t": "2.1.1 Para demonstrar o atendimento aos requisitos estabelecidos no RTQ (Anexo I), os coletores solares devem ser inspecionados e ensaiados conforme as disposições deste Anexo Específico. A conformidade do coletor solar quanto aos requisitos estabelecidos no RTQ deve ser demonstrada por meio dos ensaios e inspeções indicados na Tabela 1."}, {"c": "dou-paragraph", "t": "Tabela 1 - Ensaios de coletores solares"}, {"c": "", "t": "Item RTQ"}, {"c": "", "t": "Procedimentos"}, {"c": "", "t": "Certificação"}, {"c": "", "t": "Modelo 4"}, {"c": "", "t": "Modelo 5"}, {"c": "", "t": "Ensaios"}, {"c": "", "t": "Base Normativa"}, {"c": "", "t": "Item"}, {"c": "", "t": "Aval.Inicial"}, {"c": "", "t": "Aval.Manut."}, {"c": "", "t": "Aval.Recert."}, {"c": "", "t": "Aval.Inicial"}, {"c": "", "t": "Aval.Manut."}, {"c": "", "t": "Aval.Recert."}, {"c": "", "t": "Ano 0"}, {"c": "", "t": "24 meses"}, {"c": "", "t": "48 meses"}, {"c": "", "t": "Ano 0"}, {"c": "", "t": "36 meses"}, {"c": "", "t": "72 meses"}, {"c": "", "t": "4.1.1"}, {"c": "", "t": "Desempenho térmico"}, {"c": "", "t": "ABNT NBR 17003:2021"}, {"c": "", "t": "17"}, {"c": "", "t": "F/A"}, {"c": "", "t": "F/A"}, {"c": "", "t": "F/A"}, {"c": "", "t": "F/A"}, {"c": "", "t": "F/A"}, {"c": "", "t": "F/A"}, {"c": "", "t": "4.1.24.1.3"}, {"c": "", "t": "Pressão interna para canais de fluidos"}, {"c": "", "t": "6"}, {"c": "", "t": "F/A"}, {"c": "", "t": "F/A"}, {"c": "", "t": "F/A"}, {"c": "", "t": "F/A"}, {"c": "", "t": "F/A"}, {"c": "", "t": "F/A"}, {"c": "", "t": "4.1.4"}, {"c": "", "t": "Temperatura de estagnação padrão"}, {"c": "", "t": "7"}, {"c": "", "t": "F/A"}, {"c": "", "t": "F/A"}, {"c": "", "t": "F/A"}, {"c": "", "t": "F/A"}, {"c": "", "t": "F/A"}, {"c": "", "t": "F/A"}, {"c": "", "t": "4.1.5"}, {"c": "", "t": "Exposição"}, {"c": "", "t": "8"}, {"c": "", "t": "F/A"}, {"c": "", "t": "F/A"}, {"c": "", "t": "F/A"}, {"c": "", "t": "F/A"}, {"c": "", "t": "F/A"}, {"c": "", "t": "F/A"}, {"c": "", "t": "4.1.6"}, {"c": "", "t": "Choque térmico interno e externo I"}, {"c": "", "t": "109"}, {"c": "", "t": "F/A"}, {"c": "", "t": "F/A"}, {"c": "", "t": "F/A"}, {"c": "", "t": "F/A"}, {"c": "", "t": "F/A"}, {"c": "", "t": "F/A"}, {"c": "", "t": "4.1.5"}, {"c": "", "t": "Exposição"}, {"c": "", "t": "8"}, {"c": "", "t": "F/A"}, {"c": "", "t": "F/A"}, {"c": "", "t": "F/A"}, {"c": "", "t": "F/A"}, {"c": "", "t": "F/A"}, {"c": "", "t": "F/A"}, {"c": "", "t": "4.1.6"}, {"c": "", "t": "Choque térmico interno e externo II"}, {"c": "", "t": "109"}, {"c": "", "t": "F/A"}, {"c": "", "t": "F/A"}, {"c": "", "t": "F/A"}, {"c": "", "t": "F/A"}, {"c": "", "t": "F/A"}, {"c": "", "t": "F/A"}, {"c": "", "t": "4.1.7"}, {"c": "", "t": "Penetração de chuva"}, {"c": "", "t": "11"}, {"c": "", "t": "F"}, {"c": "", "t": "F"}, {"c": "", "t": "F"}, {"c": "", "t": "F"}, {"c": "", "t": "F"}, {"c": "", "t": "F"}, {"c": "", "t": "4.1.8"}, {"c": "", "t": "Carga mecânica positiva e negativa"}, {"c": "", "t": "13"}, {"c": "", "t": "F"}, {"c": "", "t": "F"}, {"c": "", "t": "F"}, {"c": "", "t": "F"}, {"c": "", "t": "F"}, {"c": "", "t": "F"}, {"c": "", "t": "4.1.9"}, {"c": "", "t": "Resistência ao congelamento"}, {"c": "", "t": "12"}, {"c": "", "t": "F/A"}, {"c": "", "t": "F/A"}, {"c": "", "t": "F/A"}, {"c": "", "t": "F/A"}, {"c": "", "t": "F/A"}, {"c": "", "t": "F/A"}, {"c": "", "t": "4.1.10"}, {"c": "", "t": "Resistência ao impacto"}, {"c": "", "t": "14"}, {"c": "", "t": "F"}, {"c": "", "t": "F"}, {"c": "", "t": "F"}, {"c": "", "t": "F"}, {"c": "", "t": "F"}, {"c": "", "t": "F"}, {"c": "", "t": "4.1.11"}, {"c": "", "t": "Envelhecimento acelerado"}, {"c": "", "t": "ASTM G155:25"}, {"c": "", "t": "9"}, {"c": "", "t": "F/A"}, {"c": "", "t": "F/A"}, {"c": "", "t": "F/A"}, {"c": "", "t": "F/A"}, {"c": "", "t": "F/A"}, {"c": "", "t": "F/A"}, {"c": "", "t": "5.2"}, {"c": "", "t": "Inspeção Final"}, {"c": "", "t": "ISO 9806:2017"}, {"c": "", "t": "17"}, {"c": "", "t": "F/A"}, {"c": "", "t": "F/A"}, {"c": "", "t": "F/A"}, {"c": "", "t": "F/A"}, {"c": "", "t": "F/A"}, {"c": "", "t": "F/A"}, {"c": "dou-paragraph", "t": "Legenda:"}, {"c": "dou-paragraph", "t": "\"F\" - Coletores fechados e coletores de tubo a vácuo"}, {"c": "dou-paragraph", "t": "\"A\" - Coletores abertos"}, {"c": "dou-paragraph", "t": "2.1.2 Os ensaios devem seguir os procedimentos especificados na base normativa de referência, exceto quando estabelecidas outras exigências neste RAC."}, {"c": "dou-paragraph", "t": "2.1.3 Os ensaios listados na Tabela 1, com exceção do ensaio de envelhecimento acelerado, devem ser realizados na ordem apresentada, conforme estabelecido na base normativa de referência."}, {"c": "dou-paragraph", "t": "2.1.4 Os ensaios de desempenho térmico e envelhecimento acelerado podem, opcionalmente, ser realizados separadamente em outra amostra, desde que não tenha sido submetida a ensaio."}, {"c": "dou-paragraph", "t": "2.1.5 No ensaio de desempenho térmico de coletor de aplicação piscina, deve ser utilizada a vazão de água de 4,2 l/min.m 2 , sendo a dimensão mínima da área do coletor 2,0 m²."}, {"c": "dou-paragraph", "t": "2.1.6 O ensaio de choque térmico externo e interno deve ser combinado com o ensaio de exposição, conforme as condições estabelecidas na referência normativa e considerando as condições dos subitens 2.1.7, 2.1.8 e 2.1.9."}, {"c": "dou-paragraph", "t": "2.1.7 No ensaio de exposição, o coletor deve ficar exposto por, pelo menos, 30 dias ao ar livre e irradiação global mínima (H) no plano coletor de 420 MJ/m², sem fluido, com as tubulações fechadas, exceto uma. Os valores de irradiação e da temperatura média ambiente devem ser registrados por, pelo menos, a cada 5 minutos."}, {"c": "dou-paragraph", "t": "2.1.8 No ensaio de exposição, o coletor também deve ficar exposto por, pelo menos, 30 horas ao nível mínimo de radiação solar global (G) de 800 W/m² e temperatura ambiente superior a 10 °C. Esta composição de 30 horas deve ser constituída por períodos de, pelo menos, 30 minutos."}, {"c": "dou-paragraph", "t": "2.1.9 O ensaio de exposição do coletor usando um simulador solar pode ser aplicado para atingir as 30 horas ou a irradiação global (H), ou ambas, após atingir os 30 dias de exposição ao ar livre. Neste caso de exposição do coletor no simulador solar, os ciclos de exposição devem ser de 8 horas com intervalo de no mínimo 4 horas para resfriamento do coletor até que se complete o ensaio."}, {"c": "dou-paragraph", "t": "2.1.10 Para a verificação de penetração de água após o ensaio de penetração de chuva, por meio do método da pesagem, deve ser verificada a variação de peso do coletor. Após o ensaio e antes da pesagem deverá ser realizada a pré-secagem para retirar o excesso de água. A balança utilizada deve possuir precisão menor ou igual a 5 g/m² de área bruta do coletor. Os coletores que não atenderem a essa condição, deverão ser mantidos por 24 horas na posição vertical em ambiente isento de radiação solar. Uma nova pesagem deverá ser realizada após o período citado."}, {"c": "dou-paragraph", "t": "2.1.11 Os ensaios de resistência ao congelamento e de resistência ao impacto devem ser realizados apenas quando declarado pelo Fornecedor que o coletor é resistente a essas condições."}, {"c": "dou-paragraph", "t": "2.1.12 No ensaio de resistência ao impacto deve ser utilizado o Método 2 (esfera de aço), conforme especificado na norma ABNT NBR 17003:2021."}, {"c": "dou-paragraph", "t": "2.1.13 O ensaio de envelhecimento acelerado deve ser realizado nos componentes poliméricos expostos à radiação solar ao longo da vida útil do coletor."}, {"c": "dou-paragraph", "t": "2.1.14 A critério do OCP, outros componentes poliméricos considerados críticos no quesito estanqueidade do produto ou estrutural, ou ambos, deverão ser submetidos ao ensaio."}, {"c": "dou-paragraph", "t": "2.1.15 Componentes de uma outra amostra ou componentes poliméricos individuais podem ser lacrados em separado para que sejam ensaiados em paralelo."}, {"c": "dou-paragraph", "t": "2.1.16 São considerados exemplos de componentes poliméricos presentes em coletores e que deverão ser submetidos ao ensaio de envelhecimento acelerado: passa tubo, cantos do perfil e absorvedor polimérico."}, {"c": "dou-paragraph", "t": "2.1.17 Componentes poliméricos com função apenas estética não podem ser ensaiados junto com o produto."}, {"c": "dou-paragraph", "t": "2.1.18 O ensaio de envelhecimento acelerado deve ser realizado com 1200 horas de exposição, em amostra(s) do(s) material(is) polimérico(s) utilizado(s) nos coletores, nas condições de ensaio do Ciclo n° 2, definido na base normativa de referência."}, {"c": "dou-paragraph", "t": "2.1.19 O resultado do ensaio de envelhecimento acelerado poderá ser compartilhado para coletores com características comuns pertencentes a outras famílias, não havendo necessidade de repetição desse ensaio."}, {"c": "dou-paragraph", "t": "2.1.20 Os ensaios de impacto, carga mecânica e choque térmico devem ser realizados no modelo de coletor com tipo de vidro mais frágil (vidro liso comum)."}, {"c": "dou-paragraph", "t": "2.1.21 Após a realização dos ensaios, o coletor solar deve passar pela inspeção final e ser desmontado, sendo realizadas a sua verificação dimensional, a confirmação das informações declaradas na PET e a observação da ocorrência de qualquer dano, tais como:"}, {"c": "dou-paragraph", "t": "a) vazamentos;"}, {"c": "dou-paragraph", "t": "b) deformações (expansões, contrações ou distorções);"}, {"c": "dou-paragraph", "t": "c) degradações;"}, {"c": "dou-paragraph", "t": "d) emanação de gases;"}, {"c": "dou-paragraph", "t": "e) deformação permanente de componentes;"}, {"c": "dou-paragraph", "t": "f) sinais de entrada de água e manchas na face interna do vidro;"}, {"c": "dou-paragraph", "t": "g) trincas, empenamento, corrosão;"}, {"c": "dou-paragraph", "t": "h) perda de rigidez ou segurança da estrutura;"}, {"c": "dou-paragraph", "t": "i) perda de aderência e elasticidade da vedação;"}, {"c": "dou-paragraph", "t": "j) perda de contato entre tubo e absorvedor;"}, {"c": "dou-paragraph", "t": "k) fissuras, empenamento, desgaste ou abaulamento da cobertura ou refletor;"}, {"c": "dou-paragraph", "t": "l) destruição da cobertura e danos em partes específicas;"}, {"c": "dou-paragraph", "t": "m) danos que interfiram na transmissão da radiação através da cobertura;"}, {"c": "dou-paragraph", "t": "n) degradação da pintura ou material do absorvedor; e"}, {"c": "dou-paragraph", "t": "o) qualquer dano que resulte em redução da eficiência térmica ou da vida útil."}, {"c": "dou-paragraph", "t": "2.1.22 Na inspeção, a incerteza máxima admitida nas medições é de 0,3%."}, {"c": "dou-paragraph", "t": "2.1.23 A Produção Mensal Específica de Energia (PMEe) da família do coletor deve ser calculada e informada, de acordo com o estabelecido no Anexo B deste Anexo Específico A, devendo ser utilizada para classificar os modelos segundo as classes de eficiência."}, {"c": "dou-paragraph", "t": "2.1.24 A Produção Mensal de Energia (P men ) de cada modelo de coletor, sua área bruta (AG) e eficiência térmica devem ser calculadas e informadas, de acordo com o estabelecido no Anexo B deste Anexo Específico A."}, {"c": "dou-paragraph", "t": "2.1.25 Nos ensaios da avaliação de manutenção devem ser atendidos os requisitos definidos nos subitens 2.1.23 e 2.1.24."}, {"c": "dou-paragraph", "t": "2.1.26 Quando houver inclusão de um novo modelo de coletor em uma família existente, deve ser realizada a inspeção."}, {"c": "dou-paragraph", "t": "2.1.27 Caso haja mudança no modelo base da família de coletor, o novo modelo base deve ser submetido à inspeção inicial e ao ensaio de Desempenho Térmico, devendo ser calculadas as variáveis mencionadas nos subitens 2.1.23 e 2.1.24, sendo utilizadas como referência para a reclassificação da família."}, {"c": "dou-paragraph", "t": "2.1.28 Quando houver alterações parciais no modelo base de coletor solar, devem ser realizados ensaios específicos em função das alterações propostas, conforme indicado na Tabela 2."}, {"c": "dou-paragraph", "t": "Tabela 2 - Ensaios para alterações parciais no modelo base de coletor solar"}, {"c": "", "t": "Componentes alterados"}, {"c": "", "t": "Isolamento"}, {"c": "", "t": "Cobertura"}, {"c": "", "t": "Placa Absorvedora"}, {"c": "", "t": "Tubos da serpentina"}, {"c": "", "t": "Revestimento"}, {"c": "", "t": "Moldura"}, {"c": "", "t": "Vedação"}, {"c": "", "t": "Caixa Externa Lateral"}, {"c": "", "t": "Caixa Externa Base"}, {"c": "", "t": "Área Bruta"}, {"c": "", "t": "Ensaios"}, {"c": "", "t": "Desempenho térmico"}, {"c": "", "t": "F"}, {"c": "", "t": "F"}, {"c": "", "t": "F/A"}, {"c": "", "t": "F"}, {"c": "", "t": "F"}, {"c": "", "t": "F"}, {"c": "", "t": "F"}, {"c": "", "t": "F/A"}, {"c": "", "t": "Pressão interna"}, {"c": "", "t": "A"}, {"c": "", "t": "F"}, {"c": "", "t": "Resistência à alta temperatura"}, {"c": "", "t": "F"}, {"c": "", "t": "F"}, {"c": "", "t": "F/A"}, {"c": "", "t": "F"}, {"c": "", "t": "F"}, {"c": "", "t": "F"}, {"c": "", "t": "Exposição I (10 h)"}, {"c": "", "t": "A"}, {"c": "", "t": "F"}, {"c": "", "t": "F"}, {"c": "", "t": "Choque térmico interno e externo I"}, {"c": "", "t": "F"}, {"c": "", "t": "A"}, {"c": "", "t": "F"}, {"c": "", "t": "F"}, {"c": "", "t": "Exposição II (20 h)"}, {"c": "", "t": "A"}, {"c": "", "t": "F"}, {"c": "", "t": "F"}, {"c": "", "t": "Choque térmico interno e externo II"}, {"c": "", "t": "F"}, {"c": "", "t": "A"}, {"c": "", "t": "F"}, {"c": "", "t": "F"}, {"c": "", "t": "Penetração de chuva"}, {"c": "", "t": "F"}, {"c": "", "t": "F"}, {"c": "", "t": "F"}, {"c": "", "t": "F"}, {"c": "", "t": "Carga mecânica"}, {"c": "", "t": "F"}, {"c": "", "t": "F"}, {"c": "", "t": "F"}, {"c": "", "t": "F"}, {"c": "", "t": "F"}, {"c": "", "t": "Resistência ao congelamento"}, {"c": "", "t": "F"}, {"c": "", "t": "A"}, {"c": "", "t": "F"}, {"c": "", "t": "A"}, {"c": "", "t": "Resistência ao impacto"}, {"c": "", "t": "F"}, {"c": "", "t": "Envelhecimento acelerado"}, {"c": "", "t": "F"}, {"c": "", "t": "F/A"}, {"c": "", "t": "F"}, {"c": "", "t": "F"}, {"c": "", "t": "Inspeção final"}, {"c": "", "t": "F"}, {"c": "", "t": "F"}, {"c": "", "t": "F/A"}, {"c": "", "t": "F"}, {"c": "", "t": "F"}, {"c": "", "t": "F"}, {"c": "", "t": "F"}, {"c": "", "t": "F"}, {"c": "", "t": "F"}, {"c": "", "t": "F/A"}, {"c": "dou-paragraph", "t": "Legenda:"}, {"c": "dou-paragraph", "t": "\"F\" - Coletores fechados e coletores de tubo à vácuo"}, {"c": "dou-paragraph", "t": "\"A\" - Coletores abertos"}, {"c": "dou-paragraph", "t": "2.2 Definição da Amostragem"}, {"c": "dou-paragraph", "t": "2.2.1 Para a realização dos ensaios de coletores, devem ser coletadas as unidades de amostra segundo o modelo de distribuição da Tabela 3."}, {"c": "dou-paragraph", "t": "Tabela 3 - Distribuição da amostra para ensaios"}, {"c": "", "t": "Amostra"}, {"c": "", "t": "Ensaios / Inspeção"}, {"c": "", "t": "Base Normativa"}, {"c": "", "t": "Prova"}, {"c": "", "t": "Contraprova"}, {"c": "", "t": "Testemunha"}, {"c": "", "t": "Desempenho térmico"}, {"c": "", "t": "ABNT NBR 17003:2021"}, {"c": "", "t": "1 unidade do modelo base da família"}, {"c": "", "t": "1 unidade do modelo base da família"}, {"c": "", "t": "1 unidade do modelo base da família"}, {"c": "", "t": "Pressão interna para canais de fluidos"}, {"c": "", "t": "ABNT NBR 17003:2021"}, {"c": "", "t": "1 unidade a cada 5 modelos da família"}, {"c": "", "t": "1 unidade do(s) mesmo(s) modelo(s) da prova"}, {"c": "", "t": "1 unidade do(s) mesmo(s) modelo(s) da prova"}, {"c": "", "t": "Temperatura de estagnação padrão"}, {"c": "", "t": "ABNT NBR 17003:2021"}, {"c": "", "t": "Exposição"}, {"c": "", "t": "ABNT NBR 17003:2021"}, {"c": "", "t": "Choque térmico interno e externo I"}, {"c": "", "t": "ABNT NBR 17003:2021"}, {"c": "", "t": "Exposição"}, {"c": "", "t": "ABNT NBR 17003:2021"}, {"c": "", "t": "Choque térmico interno e externo II"}, {"c": "", "t": "ABNT NBR 17003:2021"}, {"c": "", "t": "Penetração de chuva"}, {"c": "", "t": "ABNT NBR 17003:2021"}, {"c": "", "t": "Carga mecânica positiva e negativa"}, {"c": "", "t": "ABNT NBR 17003:2021"}, {"c": "", "t": "Resistência ao congelamento"}, {"c": "", "t": "ABNT NBR 17003:2021"}, {"c": "", "t": "Resistência ao impacto"}, {"c": "", "t": "ABNT NBR 17003:2021"}, {"c": "", "t": "Envelhecimento acelerado"}, {"c": "", "t": "ASTM G155:25"}, {"c": "", "t": "Inspeção Final"}, {"c": "", "t": "ISO 9806:2025"}, {"c": "dou-paragraph", "t": "2.2.2 O ensaio de Desempenho Térmico deve ser realizado na unidade do modelo base, e a(s) outra(s) unidade(s) da amostra deve(m) ser submetida(s) aos demais ensaios."}, {"c": "dou-paragraph", "t": "2.2.3 No caso de reprovação de ensaio(s) na amostra de prova, devem ser realizados nas amostras de contraprova e testemunha apenas os ensaios reprovados na amostra de prova."}, {"c": "dou-paragraph", "t": "2.2.4 O OCP pode utilizar o modelo base de coletor para a realização dos demais ensaios conforme Tabela 3, além do ensaio de desempenho térmico."}, {"c": "dou-paragraph", "t": "2.2.5 Nos ensaios da avaliação de manutenção, o ensaio de Desempenho Térmico deve ser realizado no coletor de menor dimensão da família, e nos demais ensaios, devem ser ensaiados modelos diferentes do modelo ensaiado na etapa de avaliação inicial."}, {"c": "dou-paragraph", "t": "2.2.6 Os ensaios da avaliação de manutenção não necessitam ser realizados obrigatoriamente no modelo base, ficando a critério do OCP a seleção do modelo a ser ensaiado."}, {"c": "dou-paragraph", "t": "2.3 Critérios de Aceitação e Rejeição"}, {"c": "dou-paragraph", "t": "2.3.1 Os critérios de aceitação e rejeição estão definidos na base normativa de referência, além dos seguintes."}, {"c": "dou-paragraph", "t": "2.3.2 O coletor é conforme com os requisitos 4.1.2 a 4.1.12 do RTQ se, após inspeção final, não apresentar falha grave, tal como:"}, {"c": "dou-paragraph", "t": "a) danos na cobertura ou em seus componentes;"}, {"c": "dou-paragraph", "t": "b) danos que interfiram na transmissão da radiação através da cobertura;"}, {"c": "dou-paragraph", "t": "c) degradação da pintura ou material do absorvedor;"}, {"c": "dou-paragraph", "t": "d) vazamento;"}, {"c": "dou-paragraph", "t": "e) deformação que resulte em contato permanente entre absorvedor e cobertura;"}, {"c": "dou-paragraph", "t": "f) quebra ou deformação permanente da cobertura ou de seus elementos de fixação;"}, {"c": "dou-paragraph", "t": "g) quebra ou deformação permanente da caixa externa ou dos elementos de fixação;"}, {"c": "dou-paragraph", "t": "h) perda de vácuo; e"}, {"c": "dou-paragraph", "t": "i) acúmulo de umidade (gotículas) em forma de condensação ou manchas provenientes de emanação de gases na face interna da cobertura excedendo 20% da área de abertura que resulte em redução da eficiência térmica em maior ou igual a 6% do verificado no ensaio de Desempenho Térmico."}, {"c": "dou-paragraph", "t": "2.3.3 O coletor é conforme se, após o ensaio de envelhecimento acelerado, o(s) material(is) polimérico(s) não apresentar(em) sinais de desgaste mecânico, como craqueamento e fissuras, ou de desgaste corrosivo."}, {"c": "dou-paragraph", "t": "2.3.4 O coletor é conforme se, no ensaio de verificação de penetração de água, após a repetição da pesagem, a variação de peso não for maior que 30 g/m² de área bruta do coletor."}, {"c": "dou-paragraph", "t": "2.3.5 O coletor é conforme se, após o ensaio de choque térmico, não apresentar fissuras, distorções e deformações."}, {"c": "dou-paragraph", "t": "2.3.6 A evidência de penetração de água no coletor solar após o choque térmico deve ser obtida por meio do ensaio de penetração de chuva, sendo que a constatação de penetração de água não constitui critério de reprovação."}, {"c": "dou-paragraph", "t": "2.3.7 O coletor é conforme se, após o ensaio de resistência ao impacto, resista ao impacto de altura igual a 2,00 m."}, {"c": "dou-paragraph", "t": "2.3.8 No resultado do cálculo da PMEe, a tolerância para o desvio da PMEe do coletor solar deve observar o seguinte:"}, {"c": "dou-paragraph", "t": "a) a PMEe obtida para o modelo base do coletor deve possuir desvio relativo menor ou igual a ± 6,00%, em relação aos resultados da etapa de Avaliação Inicial. Caso o desvio relativo seja menor do que - 6,00%, a amostra é considerada não conforme e o tratamento da não conformidade deve incluir a nova declaração da PMEe a partir da média aritmética entre os valores obtidos nas amostras prova, contraprova e, quando houver, testemunha. Caso o desvio relativo seja maior do que 6,00%, fica a critério do fornecedor a realização dos ensaios de contraprova e testemunha para a nova declaração da PMEe a partir da média aritmética entre os valores obtidos; e"}, {"c": "dou-paragraph", "t": "b) a PMEe obtida para demais modelos de coletor solar pode variar do valor obtido para o modelo base em até + 6,00%. Caso os valores obtidos respeitem essa tolerância, a amostra é considerada conforme e não deve haver nova declaração do valor da PMEe. Caso contrário, a amostra deve ser considerada não conforme."}, {"c": "dou-paragraph", "t": "ANEXO A - MODELOS DE PLANILHAS DE ESPECIFICAÇÕES TÉCNICAS (PET)"}, {"c": "dou-paragraph", "t": "ANEXO B - DETALHAMENTO DOS PROCEDIMENTOS DE CÁLCULOS"}, {"c": "dou-paragraph", "t": "3.3 Para o cálculo da Equação 3, deve ser adotado um valor constante para G = 800 W/m 2 ."}, {"c": "dou-paragraph", "t": "4. FAIXAS DE CLASSIFICAÇÃO DO DESEMPENHO TÉRMICO DOS COLETORES SOLARES"}, {"c": "dou-paragraph", "t": "4.1 A classificação da eficiência para produção de energia dos coletores solares deve ser determinada de acordo com a Tabela 2."}, {"c": "dou-paragraph", "t": "Tabela 2 - Faixas de Classificação da Eficiência dos Coletores Solares"}, {"c": "", "t": "Classe"}, {"c": "", "t": "Produção Específica Mensal (kWh/mês.m 2 )"}, {"c": "", "t": "Coletor Solar - Aplicação Banho"}, {"c": "", "t": "Coletor Solar - Aplicação Piscina"}, {"c": "", "t": "A"}, {"c": "", "t": "80,3 < PMEe"}, {"c": "", "t": "98,0 < PMEe"}, {"c": "", "t": "B"}, {"c": "", "t": "73,3 < PMEe < 80,3"}, {"c": "", "t": "90,0 < PMEe < 98,0"}, {"c": "", "t": "C"}, {"c": "", "t": "66,3 < PMEe < 73,3"}, {"c": "", "t": "80,0 < PMEe < 90,0"}, {"c": "", "t": "D"}, {"c": "", "t": "59,3 < PMEe < 66,3"}, {"c": "", "t": "70,0 < PMEe < 80,0"}, {"c": "", "t": "E"}, {"c": "", "t": "52,3 < PMEe < 59,3"}, {"c": "", "t": "65,0 < PMEe <70,0"}, {"c": "dou-paragraph", "t": "5. TOLERÂNCIAS APLICÁVEIS AO COLETOR SOLAR PLANO"}, {"c": "dou-paragraph", "t": "Tabela 3 - Tolerâncias aplicáveis ao coletor solar plano, conforme declarado na PET"}, {"c": "", "t": "Verificação"}, {"c": "", "t": "Tolerâncias"}, {"c": "", "t": "Dimensões Externas"}, {"c": "", "t": "Área bruta"}, {"c": "", "t": "± 1%"}, {"c": "", "t": "Área transparente"}, {"c": "", "t": "± 1%"}, {"c": "", "t": "Quantidade de travessas"}, {"c": "", "t": "0"}, {"c": "", "t": "Cobertura"}, {"c": "", "t": "Espessura do vidro"}, {"c": "", "t": "± 10%"}, {"c": "", "t": "Espessura do polímero"}, {"c": "", "t": "± 20%"}, {"c": "", "t": "Espaçamento llaca absorvedora/cobertura"}, {"c": "", "t": "± 5 mm"}, {"c": "", "t": "Absorvedor"}, {"c": "", "t": "Espessura do alumínio liso e suas ligas"}, {"c": "", "t": "± 10%"}, {"c": "", "t": "Espessura do alumínio extrudado e suas ligas"}, {"c": "", "t": "± 15%"}, {"c": "", "t": "Espessura do cobre e suas ligas"}, {"c": "", "t": "± 10%"}, {"c": "", "t": "Espessura do polímero"}, {"c": "", "t": "± 20%"}, {"c": "", "t": "Tubulação / Serpentina"}, {"c": "", "t": "Número de tubos"}, {"c": "", "t": "0"}, {"c": "", "t": "Diâmetro externo - cobre"}, {"c": "", "t": "± 1 mm"}, {"c": "", "t": "Diâmetro externo - aço"}, {"c": "", "t": "± 1 mm"}, {"c": "", "t": "Diâmetro externo - polímeros"}, {"c": "", "t": "± 2 mm"}, {"c": "", "t": "Diâmetro interno - cobre"}, {"c": "", "t": "± 1 mm"}, {"c": "", "t": "Verificação"}, {"c": "", "t": "Tolerâncias"}, {"c": "", "t": "Diâmetro interno - aço"}, {"c": "", "t": "± 1 mm"}, {"c": "", "t": "Diâmetro interno - polímeros"}, {"c": "", "t": "± 2 mm"}, {"c": "", "t": "Calha Coletora"}, {"c": "", "t": "Número de calhas"}, {"c": "", "t": "0"}, {"c": "", "t": "Diâmetro externo - Cobre"}, {"c": "", "t": "± 1 mm"}, {"c": "", "t": "Diâmetro externo - aço"}, {"c": "", "t": "± 1 mm"}, {"c": "", "t": "Diâmetro externo - polímeros"}, {"c": "", "t": "± 2 mm"}, {"c": "", "t": "Diâmetro interno - cobre"}, {"c": "", "t": "± 1 mm"}, {"c": "", "t": "Diâmetro interno - aço"}, {"c": "", "t": "± 1 mm"}, {"c": "", "t": "Diâmetro interno - polímeros"}, {"c": "", "t": "± 2 mm"}, {"c": "", "t": "Isolamento Térmico (base e lateral)"}, {"c": "", "t": "Espessura - fibra de vidro"}, {"c": "", "t": "± 20%"}, {"c": "", "t": "Espessura - lã de rocha"}, {"c": "", "t": "± 20%"}, {"c": "", "t": "Espessura - lã de PET"}, {"c": "", "t": "± 20%"}, {"c": "", "t": "Espessura - polímeros"}, {"c": "", "t": "± 20%"}, {"c": "", "t": "Caixa Externa"}, {"c": "", "t": "Espessura do alumínio liso e suas ligas"}, {"c": "", "t": "± 10%"}, {"c": "", "t": "Espessura do alumínio extrudado e suas ligas"}, {"c": "", "t": "± 15%"}, {"c": "", "t": "Espessura do alumínio stucco e suas ligas"}, {"c": "", "t": "± 10%"}, {"c": "", "t": "Espessura do polímero"}, {"c": "", "t": "± 20%"}, {"c": "dou-paragraph", "t": "Tabela 4 - Tolerâncias aplicáveis ao coletor tubo à vácuo, conforme declarado na PET"}, {"c": "", "t": "Verificação"}, {"c": "", "t": "Tolerâncias"}, {"c": "", "t": "Dimensões Externas"}, {"c": "", "t": "Área bruta"}, {"c": "", "t": "± 1%"}, {"c": "", "t": "Área de abertura"}, {"c": "", "t": "± 1%"}, {"c": "", "t": "Comprimento do cabeçote"}, {"c": "", "t": "± 10 mm"}, {"c": "", "t": "Largura / Altura da seção transversal do cabeçote"}, {"c": "", "t": "± 10 mm"}, {"c": "", "t": "Tubos à Vácuo"}, {"c": "", "t": "Quantidade de tubos"}, {"c": "", "t": "0"}, {"c": "", "t": "Diâmetro externo dos tubos"}, {"c": "", "t": "± 1 mm"}, {"c": "", "t": "Diâmetro interno dos tubos"}, {"c": "", "t": "± 1 mm"}, {"c": "dou-paragraph", "t": "ANEXO ESPECÍFICO B - RESERVATÓRIOS TERMOSSOLARES"}, {"c": "dou-paragraph", "t": "1. DOCUMENTOS COMPLEMENTARES"}, {"c": "", "t": "ABNT NBR 10185:2018"}, {"c": "", "t": "Reservatórios termossolares para líquidos destinados a sistemas de energia solar - Método de ensaio para desempenho térmico"}, {"c": "", "t": "ABNT NBR 16641:2023"}, {"c": "", "t": "Reservatórios termossolares - Requisitos específicos para utilização em sistemas de acumulação de energia solar térmica - Segurança mecânica e elétrica"}, {"c": "", "t": "ASTM G155:25"}, {"c": "", "t": "Standard Practice for Operating Xenon Arc Light Apparatus for Exposure of Materials"}, {"c": "dou-paragraph", "t": "2. ENSAIOS"}, {"c": "dou-paragraph", "t": "2.1 Definição dos Ensaios a Serem Realizados"}, {"c": "dou-paragraph", "t": "2.1.1 Para demonstrar o atendimento aos requisitos estabelecidos no RTQ (Anexo I), os reservatórios termossolares devem ser inspecionados e ensaiados conforme as disposições deste Anexo Específico."}, {"c": "dou-paragraph", "t": "2.1.2 A conformidade dos reservatórios quanto aos requisitos estabelecidos no RTQ deve ser demonstrada por meio dos ensaios e inspeções indicados na Tabela 1."}, {"c": "dou-paragraph", "t": "Tabela 1 - Ensaios de reservatórios termossolares"}, {"c": "", "t": "Item RTQ"}, {"c": "", "t": "Procedimentos"}, {"c": "", "t": "Certificação"}, {"c": "", "t": "Modelo 4"}, {"c": "", "t": "Modelo 5"}, {"c": "", "t": "Ensaios"}, {"c": "", "t": "Base Normativa"}, {"c": "", "t": "Item"}, {"c": "", "t": "Aval.Inicial"}, {"c": "", "t": "Aval.Manut."}, {"c": "", "t": "Aval.Recert."}, {"c": "", "t": "Aval.Inicial"}, {"c": "", "t": "Aval.Manut."}, {"c": "", "t": "Aval.Recert."}, {"c": "", "t": "Ano 0"}, {"c": "", "t": "24meses"}, {"c": "", "t": "48meses"}, {"c": "", "t": "Ano 0"}, {"c": "", "t": "36meses"}, {"c": "", "t": "72meses"}, {"c": "", "t": "4.2.125.4"}, {"c": "", "t": "Marcações e instruções"}, {"c": "", "t": "ABNT NBR 16641:2023"}, {"c": "", "t": "6.1"}, {"c": "", "t": "x"}, {"c": "", "t": "x"}, {"c": "", "t": "x"}, {"c": "", "t": "x"}, {"c": "", "t": "x"}, {"c": "", "t": "x"}, {"c": "", "t": "4.2.1"}, {"c": "", "t": "Volume armazenado"}, {"c": "", "t": "6.2"}, {"c": "", "t": "x"}, {"c": "", "t": "x"}, {"c": "", "t": "x"}, {"c": "", "t": "x"}, {"c": "", "t": "x"}, {"c": "", "t": "x"}, {"c": "", "t": "4.2.2"}, {"c": "", "t": "Pressão hidrostática"}, {"c": "", "t": "6.3"}, {"c": "", "t": "x"}, {"c": "", "t": "x"}, {"c": "", "t": "x"}, {"c": "", "t": "x"}, {"c": "", "t": "x"}, {"c": "", "t": "x"}, {"c": "", "t": "4.2.3"}, {"c": "", "t": "Perda específica deenergia mensal"}, {"c": "", "t": "ABNT NBR10185:2018"}, {"c": "", "t": "AnexoD"}, {"c": "", "t": "x"}, {"c": "", "t": "x"}, {"c": "", "t": "x"}, {"c": "", "t": "x"}, {"c": "", "t": "x"}, {"c": "", "t": "x"}, {"c": "", "t": "4.2.4"}, {"c": "", "t": "Tensão suportável"}, {"c": "", "t": "ABNT NBR 16641:2023"}, {"c": "", "t": "6.4"}, {"c": "", "t": "x"}, {"c": "", "t": "x"}, {"c": "", "t": "x"}, {"c": "", "t": "x"}, {"c": "", "t": "x"}, {"c": "", "t": "x"}, {"c": "", "t": "4.2.5"}, {"c": "", "t": "Corrente de fuga"}, {"c": "", "t": "6.5"}, {"c": "", "t": "x"}, {"c": "", "t": "x"}, {"c": "", "t": "x"}, {"c": "", "t": "x"}, {"c": "", "t": "x"}, {"c": "", "t": "x"}, {"c": "", "t": "4.2.6"}, {"c": "", "t": "Potência absorvida"}, {"c": "", "t": "6.6"}, {"c": "", "t": "x"}, {"c": "", "t": "x"}, {"c": "", "t": "x"}, {"c": "", "t": "x"}, {"c": "", "t": "x"}, {"c": "", "t": "x"}, {"c": "", "t": "4.2.7"}, {"c": "", "t": "Resistência ao calor e fogo"}, {"c": "", "t": "6.7"}, {"c": "", "t": "x"}, {"c": "", "t": "x"}, {"c": "", "t": "x"}, {"c": "", "t": "x"}, {"c": "", "t": "x"}, {"c": "", "t": "x"}, {"c": "", "t": "4.2.8"}, {"c": "", "t": "Resistência à oxidação"}, {"c": "", "t": "6.8"}, {"c": "", "t": "x"}, {"c": "", "t": "x"}, {"c": "", "t": "x"}, {"c": "", "t": "x"}, {"c": "", "t": "x"}, {"c": "", "t": "x"}, {"c": "", "t": "4.2.9"}, {"c": "", "t": "Envelhecimento acelerado"}, {"c": "", "t": "ASTM G155:25"}, {"c": "", "t": "9"}, {"c": "", "t": "x"}, {"c": "", "t": "x"}, {"c": "", "t": "x"}, {"c": "", "t": "x"}, {"c": "", "t": "x"}, {"c": "", "t": "x"}, {"c": "dou-paragraph", "t": "2.1.3 Os ensaios de Tensão suportável, Corrente de Fuga, Potência Absorvida e Resistência ao Calor e Fogo aplicam-se somente aos reservatórios que possuem apoio elétrico."}, {"c": "dou-paragraph", "t": "2.1.4 Para famílias de reservatórios constituídas apenas por modelos sem resistência elétrica, deverá ser realizado o ensaio de Resistência ao Enferrujamento."}, {"c": "dou-paragraph", "t": "2.1.5 O ensaio de envelhecimento acelerado deve ser realizado nos componentes poliméricos expostos à radiação solar ao longo da vida útil do reservatório."}, {"c": "dou-paragraph", "t": "2.1.6 A critério do OCP, outros componentes poliméricos considerados críticos no quesito estanqueidade do produto, ou estrutural, ou ambos, deverão ser submetidos ao ensaio."}, {"c": "dou-paragraph", "t": "2.1.7 Componentes de uma outra amostra ou componentes poliméricos individuais podem ser lacrados em separado para que sejam ensaiados em paralelo."}, {"c": "dou-paragraph", "t": "2.1.8 São considerados exemplos de componentes poliméricos presentes em reservatórios e que deverão ser submetidos ao ensaio de envelhecimento acelerado: passa tubo, passa fio, pés, tampa e corpo externo."}, {"c": "dou-paragraph", "t": "2.1.9 Componentes poliméricos com função apenas estética não podem ser ensaiados junto com o produto."}, {"c": "dou-paragraph", "t": "2.1.10 O ensaio de envelhecimento acelerado deve ser realizado com 1200 horas de exposição, em amostra(s) do(s) material(is) polimérico(s) utilizado(s) nos reservatórios, nas condições de ensaio do Ciclo n°2, conforme definido pela base normativa de referência."}, {"c": "dou-paragraph", "t": "2.1.11 A estimativa de Perda Específica de Energia Mensal da família de reservatório deve ser calculada e informada, devendo estar conforme os limites máximos estabelecidos no subitem 4.2.3 do RTQ."}, {"c": "dou-paragraph", "t": "2.1.12 Nos ensaios da avaliação de manutenção deve ser atendido o requisito definido no subitem 2.1.11."}, {"c": "dou-paragraph", "t": "2.1.13 Para a inclusão de um novo modelo de reservatório em uma família existente, caso a família não possua modelo já certificado com resistência elétrica, os ensaios de Tensão Suportável, Corrente de Fuga, Potência Absorvida e Resistência ao Calor e Fogo são requeridos."}, {"c": "dou-paragraph", "t": "2.1.14 Os resultados dos ensaios listados abaixo poderão ser compartilhados para reservatórios com características comuns, pertencentes a outras famílias, não havendo necessidade de repetição desses ensaios:"}, {"c": "dou-paragraph", "t": "a) Marcações e instruções;"}, {"c": "dou-paragraph", "t": "b) Tensão suportável;"}, {"c": "dou-paragraph", "t": "c) Corrente de fuga;"}, {"c": "dou-paragraph", "t": "d) Potência absorvida;"}, {"c": "dou-paragraph", "t": "e) Resistência ao calor e fogo;"}, {"c": "dou-paragraph", "t": "f) Resistência ao enferrujamento; e"}, {"c": "dou-paragraph", "t": "g) Envelhecimento acelerado."}, {"c": "dou-paragraph", "t": "2.2 Definição da Amostragem"}, {"c": "dou-paragraph", "t": "2.2.1 Para a realização dos ensaios de reservatórios, devem ser coletadas as unidades de amostra segundo o modelo de distribuição da Tabela 2."}, {"c": "dou-paragraph", "t": "Tabela 2 - Distribuição da amostra para ensaios"}, {"c": "", "t": "Amostra"}, {"c": "", "t": "Ensaios / Inspeção"}, {"c": "", "t": "Base Normativa"}, {"c": "", "t": "Prova"}, {"c": "", "t": "Contraprova"}, {"c": "", "t": "Testemunha"}, {"c": "", "t": "Volume armazenado"}, {"c": "", "t": "ABNT NBR16641:2023"}, {"c": "", "t": "1 unidade de cada volume da família"}, {"c": "", "t": "1 unidade do(s) mesmo(s) modelo(s) da prova"}, {"c": "", "t": "1 unidade do(s) mesmo(s) modelo(s) da prova"}, {"c": "", "t": "Perda específica de energia mensal"}, {"c": "", "t": "ABNT NBR10185:2018"}, {"c": "", "t": "Pressão hidrostática"}, {"c": "", "t": "ABNT NBR 16641:2023"}, {"c": "", "t": "1 unidade por família"}, {"c": "", "t": "Marcações e instruções"}, {"c": "", "t": "Tensão suportável"}, {"c": "", "t": "Corrente de fuga"}, {"c": "", "t": "Potência absorvida"}, {"c": "", "t": "Resistência ao calor e fogo"}, {"c": "", "t": "Resistência à oxidação"}, {"c": "", "t": "Envelhecimento acelerado"}, {"c": "", "t": "ASTM G155:25"}, {"c": "dou-paragraph", "t": "2.2.2 A seleção das unidades da amostra deve priorizar os modelos com resistência elétrica da família, caso existam."}, {"c": "dou-paragraph", "t": "2.2.3 O ensaio de envelhecimento acelerado pode, opcionalmente, ser realizado separadamente em outra amostra, desde que não tenha sido submetida a ensaio."}, {"c": "dou-paragraph", "t": "2.2.4 Deverão ser ensaiados um modelo por família, de cada volume, nos ensaios de Volume Armazenado e Perda Específica de Energia Mensal (Eficiência). O resultado do ensaio de Volume Armazenado e Perda Específica de Energia Mensal (Eficiência) no reservatório de baixa pressão valerá também para o de alta pressão, e vice-versa, desde que os reservatórios termossolares tenham as mesmas dimensões."}, {"c": "dou-paragraph", "t": "2.2.5 O ensaio de Pressão Hidrostática será realizado de forma aleatória dentre os modelos, executado para cada amostra de diâmetro diferente. Reservatórios com ou sem anodo, ou com ou sem resistência elétrica, e ainda horizontal ou vertical, não sofrem alterações no ensaio de Pressão Hidrostática."}, {"c": "dou-paragraph", "t": "2.2.6 Famílias de reservatórios de alta e baixa pressão, com diâmetros diferentes, devem ser submetidas ao ensaio de Pressão Hidrostática em um dos equipamentos, de forma aleatória, à escolha do OCP."}, {"c": "dou-paragraph", "t": "2.2.7 No ensaio de Pressão Hidrostática, em amostras de mesmo diâmetro, devem ser ensaiados um modelo de alta e um modelo de baixa pressão."}, {"c": "dou-paragraph", "t": "2.3 Critérios de Aceitação e Rejeição"}, {"c": "dou-paragraph", "t": "2.3.1 Os critérios de aceitação e rejeição estão definidos na base normativa de referência, além dos seguintes."}, {"c": "dou-paragraph", "t": "2.3.3 O reservatório é conforme se, após o ensaio de pressão hidrostática, na inspeção não foi identificado vazamento ou deformação permanente visível."}, {"c": "dou-paragraph", "t": "2.3.4 O reservatório é conforme se o resultado do cálculo do valor de Perda Específica de Energia Mensal Máxima, por capacidade, obedecer aos limites máximos indicados na Tabela 3."}, {"c": "dou-paragraph", "t": "Tabela 3 - Perda específica de energia mensal máxima do reservatório por capacidade"}, {"c": "", "t": "Volume nominal reservatório termossolar (l)"}, {"c": "", "t": "Perda Específica de Energia Mensal Máxima (kWh/l.mês)"}, {"c": "", "t": "100"}, {"c": "", "t": "<0,27"}, {"c": "", "t": "150"}, {"c": "", "t": "<0,27"}, {"c": "", "t": "200"}, {"c": "", "t": "<0,27"}, {"c": "", "t": "250"}, {"c": "", "t": "<0,27"}, {"c": "", "t": "300"}, {"c": "", "t": "<0,27"}, {"c": "", "t": "400"}, {"c": "", "t": "<0,22"}, {"c": "", "t": "500"}, {"c": "", "t": "<0,21"}, {"c": "", "t": "600"}, {"c": "", "t": "<0,20"}, {"c": "", "t": "800"}, {"c": "", "t": "<0,18"}, {"c": "", "t": ">1000"}, {"c": "", "t": "<0,16"}, {"c": "dou-paragraph", "t": "2.3.5 Para reservatórios de sistemas acoplados de volumes intermediários, a Perda Específica de Energia Mensal Máxima considerada deve ser aquela do volume imediatamente inferior, entre os indicados na Tabela 3."}, {"c": "dou-paragraph", "t": "2.3.6 O reservatório é conforme se, após os ensaios de tensão suportável e corrente de fuga, não sofreu perfurações ou descargas disruptivas, mesmo após variados valores de tensão elétrica, ficando preservadas as suas isolações."}, {"c": "dou-paragraph", "t": "2.3.7 O reservatório é conforme se, após o ensaio de corrente de fuga, o valor medido de corrente de fuga for < 5 mA."}, {"c": "dou-paragraph", "t": "2.3.9 O reservatório é conforme se, após o ensaio de resistência ao calor e fogo, a velocidade de propagação da chama estiver em conformidade com os critérios da base normativa de referência."}, {"c": "dou-paragraph", "t": "2.3.10 O reservatório é conforme se, após o ensaio de envelhecimento acelerado, o(s) material(is) polimérico(s) não apresentar(em) sinais de desgaste mecânico, como craqueamento e fissuras, ou de desgaste corrosivo."}, {"c": "dou-paragraph", "t": "2.3.11 O reservatório é conforme se, após o ensaio de Perda Específica de Energia Mensal, o valor obtido de estiver entre ± 6,00% em relação ao valor obtido na etapa de Avaliação Inicial. Caso essa tolerância não seja observada e o valor obtido ainda respeite os limites mínimos, o tratamento da não conformidade deve incluir a nova declaração da Perda Específica de Energia Mensal."}, {"c": "dou-paragraph", "t": "ANEXO A - MODELO DE PLANILHA DE ESPECIFICAÇÃO TÉCNICA (PET)"}, {"c": "", "t": "PLANILHA DE ESPECIFICAÇÃO TÉCNICA (PET) - RESERVATÓRIO TERMOSSOLAR"}, {"c": "", "t": "I. Identificação do Fornecedor"}, {"c": "", "t": "(1) Razão Social:"}, {"c": "", "t": "(2) Nome Fantasia:"}, {"c": "", "t": "(3) Endereço:"}, {"c": "", "t": "(4) Telefone 01:"}, {"c": "", "t": "(5) Telefone 02:"}, {"c": "", "t": "(6) Fax:"}, {"c": "", "t": "(7) E-mail:"}, {"c": "", "t": "II. Identificação do Produto"}, {"c": "", "t": "(8) Marca:"}, {"c": "", "t": "(9) Modelo (preencher campo 36):"}, {"c": "", "t": "(10) Código / Nº Série:"}, {"c": "", "t": "(11) Quantidade de energia perdida (preenchimento após a realização do ensaio inicial):"}, {"c": "", "t": "(12) Capacidade (litros):"}, {"c": "", "t": "(13) Reservatório de Nível: ( ) S ( ) N"}, {"c": "", "t": "III. Dimensões (Não incluir tubulações e caixa de proteção elétrica)"}, {"c": "", "t": "III.A. Dimensões Externas"}, {"c": "", "t": "(14) Comprimento máximo (mm):"}, {"c": "", "t": "(15) Diâmetro (mm):"}, {"c": "", "t": "III.B. Dimensões do Cilindro Interno"}, {"c": "", "t": "(16) Comprimento (mm):"}, {"c": "", "t": "(17) Diâmetro (mm):"}, {"c": "", "t": "IV. Materiais e Especificações (Se as espessuras forem variáveis, especifique os valores máx. e mín.)"}, {"c": "", "t": "IV.A. Revestimento Externo"}, {"c": "", "t": "IV.B. Cilindro Interno"}, {"c": "", "t": "(18) Material:"}, {"c": "", "t": "(19) Material:"}, {"c": "", "t": "(20) Espessura (mm):"}, {"c": "", "t": "(21) Espessura (mm):"}, {"c": "", "t": "IV.C. Isolamento Térmico"}, {"c": "", "t": "(22) Material:"}, {"c": "", "t": "(23) Espessura Superfície Cilíndrica (mm):"}, {"c": "", "t": "(24) Espessura Faces Laterais (mm):"}, {"c": "", "t": "V. Características Gerais do Reservatório"}, {"c": "", "t": "(25) Peso do reservatório(kg):"}, {"c": "", "t": "(26) Pressão de trabalho (kPa):"}, {"c": "", "t": "(27) Fluido de trabalho:"}, {"c": "", "t": "VI. Sistema Elétrico Auxiliar"}, {"c": "", "t": "(28) ( ) Não se aplica (ir para campo 32)"}, {"c": "", "t": "(29) ( ) Sim, se aplica (preencher 30 e 31)"}, {"c": "", "t": "(30) Potência elétrica (kW):"}, {"c": "", "t": "(31) Presença de fio-terra: ( ) S ( ) N"}, {"c": "", "t": "VII. Termostato (posição medida a partir da base do reservatório)"}, {"c": "", "t": "(32) Posição (mm):"}, {"c": "", "t": "(33) Uso de materiais poliméricos reciclados ( ) S ( ) N"}, {"c": "", "t": "(34) Presença de substâncias tóxicas que possam migrar para a água e representar risco à saúde humana ( ) S ( ) N"}, {"c": "", "t": "(35) Grau de Proteção IP24 ( ) S ( ) N"}, {"c": "", "t": "VIII. Indicação do Modelo da Família"}, {"c": "", "t": "(36) Modelo:"}, {"c": "", "t": "IX. Observações"}, {"c": "", "t": "DATA:"}, {"c": "", "t": "ASSINATURA DO FORNECEDOR:"}, {"c": "dou-paragraph", "t": "ANEXO ESPECÍFICO C - SISTEMAS ACOPLADOS"}, {"c": "dou-paragraph", "t": "1. DOCUMENTOS COMPLEMENTARES"}, {"c": "", "t": "ABNT NBR 10185:2018"}, {"c": "", "t": "Reservatórios termossolares para líquidos destinados a sistemas de energia solar - Método de ensaio para desempenho térmico"}, {"c": "", "t": "ABNT NBR 17003:2021"}, {"c": "", "t": "Sistemas solares térmicos e seus componentes - Coletores solares - Requisitos gerais e métodos de ensaio"}, {"c": "", "t": "ABNT NBR 16641:2023"}, {"c": "", "t": "Reservatórios termossolares - Requisitos específicos para utilização em sistemas de acumulação de energia solar térmica - Segurança mecânica e elétrica"}, {"c": "", "t": "ASTM G155-25"}, {"c": "", "t": "Operating Xenon Arc Lamp Apparatus for Exposure of Materials"}, {"c": "", "t": "ISO 9806:2025"}, {"c": "", "t": "Solar energy - Solar thermal collectors - Test methods"}, {"c": "", "t": "ISO 9459-2:1995"}, {"c": "", "t": "Solar heating - Domestic water heating systems - Part 2: Outdoor test methods for system performance characterization and yearly performance prediction of solar-only systems"}, {"c": "dou-paragraph", "t": "2. ENSAIOS"}, {"c": "dou-paragraph", "t": "2.1 Definição dos Ensaios a Serem Realizados"}, {"c": "dou-paragraph", "t": "2.1.1 Para demonstrar o atendimento aos requisitos estabelecidos no RTQ (Anexo I), os sistemas acoplados devem ser inspecionados e ensaiados conforme as disposições deste Anexo Específico."}, {"c": "dou-paragraph", "t": "2.1.2 A conformidade do sistema acoplado quanto aos requisitos estabelecidos no RTQ deve ser demonstrada por meio dos ensaios e inspeções indicados na Tabela 1."}, {"c": "dou-paragraph", "t": "Tabela 1 - Ensaios de sistemas acoplados"}, {"c": "", "t": "Item RTQ"}, {"c": "", "t": "Procedimentos"}, {"c": "", "t": "Certificação"}, {"c": "", "t": "Modelo 4"}, {"c": "", "t": "Modelo 5"}, {"c": "", "t": "Ensaios"}, {"c": "", "t": "Base Normativa"}, {"c": "", "t": "Item"}, {"c": "", "t": "Aval.Inicial"}, {"c": "", "t": "Aval.Manut."}, {"c": "", "t": "Aval.Recert."}, {"c": "", "t": "Aval.Inicial"}, {"c": "", "t": "Aval.Manut."}, {"c": "", "t": "Aval.Recert."}, {"c": "", "t": "Ano 0"}, {"c": "", "t": "24 meses"}, {"c": "", "t": "48 meses"}, {"c": "", "t": "Ano 0"}, {"c": "", "t": "36 meses"}, {"c": "", "t": "72 meses"}, {"c": "", "t": "4.3.34.3.4"}, {"c": "", "t": "Desempenho térmico"}, {"c": "", "t": "ISO 9459-2:1995"}, {"c": "", "t": "7"}, {"c": "", "t": "S"}, {"c": "", "t": "S"}, {"c": "", "t": "S"}, {"c": "", "t": "S"}, {"c": "", "t": "S"}, {"c": "", "t": "S"}, {"c": "", "t": "4.1.24.1.3"}, {"c": "", "t": "Pressão interna para canais de fluidos"}, {"c": "", "t": "ABNT NBR 17003:2021"}, {"c": "", "t": "6"}, {"c": "", "t": "C"}, {"c": "", "t": "C"}, {"c": "", "t": "C"}, {"c": "", "t": "C"}, {"c": "", "t": "C"}, {"c": "", "t": "C"}, {"c": "", "t": "4.1.4"}, {"c": "", "t": "Temperatura de estagnação padrão"}, {"c": "", "t": "7"}, {"c": "", "t": "C"}, {"c": "", "t": "C"}, {"c": "", "t": "C"}, {"c": "", "t": "C"}, {"c": "", "t": "C"}, {"c": "", "t": "C"}, {"c": "", "t": "4.1.5"}, {"c": "", "t": "Exposição"}, {"c": "", "t": "8"}, {"c": "", "t": "C"}, {"c": "", "t": "C"}, {"c": "", "t": "C"}, {"c": "", "t": "C"}, {"c": "", "t": "C"}, {"c": "", "t": "C"}, {"c": "", "t": "4.1.6"}, {"c": "", "t": "Choque térmico interno e externo I"}, {"c": "", "t": "109"}, {"c": "", "t": "C"}, {"c": "", "t": "C"}, {"c": "", "t": "C"}, {"c": "", "t": "C"}, {"c": "", "t": "C"}, {"c": "", "t": "C"}, {"c": "", "t": "4.1.5"}, {"c": "", "t": "Exposição"}, {"c": "", "t": "8"}, {"c": "", "t": "C"}, {"c": "", "t": "C"}, {"c": "", "t": "C"}, {"c": "", "t": "C"}, {"c": "", "t": "C"}, {"c": "", "t": "C"}, {"c": "", "t": "4.1.6"}, {"c": "", "t": "Choque térmico interno e externo II"}, {"c": "", "t": "109"}, {"c": "", "t": "C"}, {"c": "", "t": "C"}, {"c": "", "t": "C"}, {"c": "", "t": "C"}, {"c": "", "t": "C"}, {"c": "", "t": "C"}, {"c": "", "t": "4.1.7"}, {"c": "", "t": "Penetração de chuva"}, {"c": "", "t": "11"}, {"c": "", "t": "C"}, {"c": "", "t": "C"}, {"c": "", "t": "C"}, {"c": "", "t": "C"}, {"c": "", "t": "C"}, {"c": "", "t": "C"}, {"c": "", "t": "4.1.8"}, {"c": "", "t": "Carga mecânica positiva e negativa"}, {"c": "", "t": "13"}, {"c": "", "t": "C"}, {"c": "", "t": "C"}, {"c": "", "t": "C"}, {"c": "", "t": "C"}, {"c": "", "t": "C"}, {"c": "", "t": "C"}, {"c": "", "t": "4.1.10"}, {"c": "", "t": "Resistência ao impacto"}, {"c": "", "t": "14"}, {"c": "", "t": "C"}, {"c": "", "t": "C"}, {"c": "", "t": "C"}, {"c": "", "t": "C"}, {"c": "", "t": "C"}, {"c": "", "t": "C"}, {"c": "", "t": "5.5"}, {"c": "", "t": "Inspeção Final"}, {"c": "", "t": "ISO 9806:2025"}, {"c": "", "t": "17"}, {"c": "", "t": "S"}, {"c": "", "t": "S"}, {"c": "", "t": "S"}, {"c": "", "t": "S"}, {"c": "", "t": "S"}, {"c": "", "t": "S"}, {"c": "", "t": "5.5"}, {"c": "", "t": "Marcações e instruções"}, {"c": "", "t": "ABNT NBR 16641:2023"}, {"c": "", "t": "6.1"}, {"c": "", "t": "R"}, {"c": "", "t": "R"}, {"c": "", "t": "R"}, {"c": "", "t": "R"}, {"c": "", "t": "R"}, {"c": "", "t": "R"}, {"c": "", "t": "4.2.1"}, {"c": "", "t": "Volume armazenado"}, {"c": "", "t": "6.2"}, {"c": "", "t": "R"}, {"c": "", "t": "R"}, {"c": "", "t": "R"}, {"c": "", "t": "R"}, {"c": "", "t": "R"}, {"c": "", "t": "R"}, {"c": "", "t": "4.2.2"}, {"c": "", "t": "Pressão hidrostática"}, {"c": "", "t": "6.3"}, {"c": "", "t": "R"}, {"c": "", "t": "R"}, {"c": "", "t": "R"}, {"c": "", "t": "R"}, {"c": "", "t": "R"}, {"c": "", "t": "R"}, {"c": "", "t": "4.2.4"}, {"c": "", "t": "Tensão suportável"}, {"c": "", "t": "6.4"}, {"c": "", "t": "R"}, {"c": "", "t": "R"}, {"c": "", "t": "R"}, {"c": "", "t": "R"}, {"c": "", "t": "R"}, {"c": "", "t": "R"}, {"c": "", "t": "4.2.5"}, {"c": "", "t": "Corrente de fuga"}, {"c": "", "t": "6.5"}, {"c": "", "t": "R"}, {"c": "", "t": "R"}, {"c": "", "t": "R"}, {"c": "", "t": "R"}, {"c": "", "t": "R"}, {"c": "", "t": "R"}, {"c": "", "t": "4.2.6"}, {"c": "", "t": "Potência elétrica absorvida"}, {"c": "", "t": "6.6"}, {"c": "", "t": "R"}, {"c": "", "t": "R"}, {"c": "", "t": "R"}, {"c": "", "t": "R"}, {"c": "", "t": "R"}, {"c": "", "t": "R"}, {"c": "", "t": "4.2.7"}, {"c": "", "t": "Resistência ao calor e fogo"}, {"c": "", "t": "6.7"}, {"c": "", "t": "R"}, {"c": "", "t": "R"}, {"c": "", "t": "R"}, {"c": "", "t": "R"}, {"c": "", "t": "R"}, {"c": "", "t": "R"}, {"c": "", "t": "4.2.8"}, {"c": "", "t": "Resistência à oxidação"}, {"c": "", "t": "6.8"}, {"c": "", "t": "R"}, {"c": "", "t": "R"}, {"c": "", "t": "R"}, {"c": "", "t": "R"}, {"c": "", "t": "R"}, {"c": "", "t": "R"}, {"c": "dou-paragraph", "t": "Legenda:"}, {"c": "dou-paragraph", "t": "\"R\" - Reservatório acoplado"}, {"c": "dou-paragraph", "t": "\"C\" - Coletores acoplado"}, {"c": "dou-paragraph", "t": "\"S\" - Sistema acoplado"}, {"c": "dou-paragraph", "t": "2.1.3 Os ensaios devem seguir os procedimentos especificados na base normativa de referência, exceto quando estabelecidas outras exigências neste RAC."}, {"c": "dou-paragraph", "t": "2.1.4 Os ensaios listados na Tabela 1 referentes a \"coletor acoplado\", com exceção do ensaio de envelhecimento acelerado, devem ser realizados na ordem apresentada, conforme estabelecido na base normativa de referência."}, {"c": "dou-paragraph", "t": "2.1.5 Os ensaios de desempenho térmico e envelhecimento acelerado podem, opcionalmente, ser realizados separadamente em outra amostra, desde que não tenha sido submetida a ensaio."}, {"c": "dou-paragraph", "t": "2.1.6 O ensaio de resistência ao impacto deve ser realizado apenas quando declarado pelo fornecedor que o coletor acoplado é resistente a essa condição."}, {"c": "dou-paragraph", "t": "2.1.7 Os ensaios listados Tabela 1 referentes a \"coletor acoplado\" podem ser realizados em unidades de amostras diferentes daquelas a serem submetidas aos ensaios referentes a \"reservatório acoplado\"."}, {"c": "dou-paragraph", "t": "2.1.8 Quando o sistema acoplado possuir reservatório de nível, com boia interna em caixa de quebra de pressão, o ensaio de desempenho térmico deverá ser realizado com a mesma vazão estabelecida na base normativa de referência, sem a utilização da caixa de quebra de pressão."}, {"c": "dou-paragraph", "t": "2.1.9 Para o ensaio de pressão interna do coletor acoplado, no caso de absorvedores orgânicos, isto é, constituídos de plásticos ou elastômeros, a temperatura de ensaio deve ser a máxima temperatura a que o absorvedor pode chegar sob as condições de estagnação, desde que menor ou igual a 90 °C. Quando a temperatura de estagnação calculada for maior que 90 °C, a temperatura de ensaio deve ser 90 °C."}, {"c": "dou-paragraph", "t": "2.1.10 O ensaio de choque térmico externo e interno do coletor acoplado deve ser combinado com o ensaio de exposição, conforme estabelecido na base normativa de referência."}, {"c": "dou-paragraph", "t": "2.1.11 Para a verificação de penetração de água após o ensaio de penetração de chuva, por meio do método da pesagem, deve ser verificada a variação de peso do coletor. Após o ensaio e antes da pesagem deverá ser realizada a pré-secagem para retirar o excesso de água. A balança utilizada deve possuir precisão menor ou igual a 5 g/m² de área bruta do coletor. Os coletores que não atenderem a essa condição, deverão ser mantidos por 24 horas na posição vertical em ambiente isento de radiação solar. Uma nova pesagem deverá ser realizada após o período citado."}, {"c": "dou-paragraph", "t": "2.1.12 Os ensaios de Tensão Suportável, Corrente de Fuga, Potência Absorvida e Resistência ao Calor e Fogo aplicam-se somente aos reservatórios acoplados que possuem apoio elétrico."}, {"c": "dou-paragraph", "t": "2.1.13 O ensaio de envelhecimento acelerado deve ser realizado nos componentes poliméricos expostos à radiação solar ao longo da vida útil do sistema acoplado."}, {"c": "dou-paragraph", "t": "2.1.14 A critério do OCP, outros componentes poliméricos considerados críticos no quesito estanqueidade do produto ou estrutural, ou ambos, deverão ser submetidos ao ensaio."}, {"c": "dou-paragraph", "t": "2.1.15 Componentes de uma outra amostra ou componentes poliméricos individuais podem ser lacrados em separado para que sejam ensaiados em paralelo."}, {"c": "dou-paragraph", "t": "2.1.16 São considerados exemplos de componentes poliméricos presentes em sistemas acoplados e que deverão ser submetidos ao ensaio de envelhecimento acelerado:"}, {"c": "dou-paragraph", "t": "a) coletor acoplado: passa tubo, cantos do perfil e absorvedor polimérico; e"}, {"c": "dou-paragraph", "t": "b) reservatório acoplado: passa tubo, passa fio, pés, tampa e corpo externo."}, {"c": "dou-paragraph", "t": "2.1.17 Componentes poliméricos com função apenas estética não podem ser ensaiados junto com o produto."}, {"c": "dou-paragraph", "t": "2.1.18 O ensaio de envelhecimento acelerado deve ser realizado com 1200 horas de exposição, em amostra(s) do(s) material(is) polimérico(s) utilizado(s) nos coletores e reservatórios acoplados, nas condições de ensaio do Ciclo n° 2, conforme definido na base normativa de referência."}, {"c": "dou-paragraph", "t": "2.1.19 Para os sistemas acoplados do tipo justaposto, caso o coletor e o reservatório acoplados já possuam Certificado de Conformidade válido, somente o ensaio de \"Desempenho térmico\" no conjunto coletor e reservatório é requerido."}, {"c": "dou-paragraph", "t": "2.1.20 A Produção Mensal Específica de Energia (PMEe) do modelo de sistema acoplado deve ser calculada e informada, de acordo com o estabelecido no Anexo B deste Anexo Específico C, devendo ser utilizada para classificá-lo segundo as classes de eficiência."}, {"c": "dou-paragraph", "t": "2.1.21 A Produção Mensal de Energia (P men ), a Área Bruta (AG) e a Eficiência Térmica Diária do modelo de sistema acoplado devem ser calculadas e informadas, de acordo com as orientações do Anexo B deste Anexo Específico C."}, {"c": "dou-paragraph", "t": "2.2 Definição da Amostragem"}, {"c": "dou-paragraph", "t": "2.2.1 Para a realização dos ensaios de sistemas acoplados, devem ser coletadas as unidades de amostra segundo o modelo de distribuição da Tabela 2."}, {"c": "dou-paragraph", "t": "Tabela 2 - Distribuição da amostra para ensaios"}, {"c": "", "t": "Ensaios / Inspeção"}, {"c": "", "t": "Base Normativa"}, {"c": "", "t": "Amostra"}, {"c": "", "t": "Prova"}, {"c": "", "t": "Contraprova"}, {"c": "", "t": "Testemunha"}, {"c": "", "t": "Desempenho térmico"}, {"c": "", "t": "ISO 9459-2:1995"}, {"c": "", "t": "1 unidade de cada modelo"}, {"c": "", "t": "1 unidade do(s) mesmo(s) modelo(s) da prova"}, {"c": "", "t": "1 unidade do(s) mesmo(s) modelo(s) da prova"}, {"c": "", "t": "Pressão interna para canais de fluidos"}, {"c": "", "t": "ABNT NBR 17003:2021"}, {"c": "", "t": "Temperatura de estagnação padrão"}, {"c": "", "t": "Exposição"}, {"c": "", "t": "Choque térmico interno e externo I"}, {"c": "", "t": "Exposição"}, {"c": "", "t": "Choque térmico interno e externo II"}, {"c": "", "t": "Penetração de chuva"}, {"c": "", "t": "Carga mecânica positiva e negativa"}, {"c": "", "t": "Resistência ao impacto"}, {"c": "", "t": "Envelhecimento acelerado"}, {"c": "", "t": "ASTM G155-25"}, {"c": "", "t": "Inspeção Final"}, {"c": "", "t": "ISO 9806:2025"}, {"c": "", "t": "Marcações e instruções"}, {"c": "", "t": "ABNT NBR 16641:2023"}, {"c": "", "t": "Volume armazenado"}, {"c": "", "t": "Pressão hidrostática"}, {"c": "", "t": "Perda específica de energia mensal"}, {"c": "", "t": "ABNT NBR 10185:2018"}, {"c": "", "t": "Tensão suportável"}, {"c": "", "t": "ABNT NBR 16641:2023"}, {"c": "", "t": "Corrente de fuga"}, {"c": "", "t": "Potência elétrica absorvida"}, {"c": "", "t": "Resistência ao calor e fogo"}, {"c": "", "t": "Resistência à oxidação"}, {"c": "", "t": "Envelhecimento acelerado"}, {"c": "", "t": "ASTM G155-25"}, {"c": "dou-paragraph", "t": "2.2.2 Para a realização dos ensaios de sistemas acoplados, devem ser observados os requisitos de amostragem aplicáveis, indicados nos subitens 2.2 dos Anexos Específicos A e B."}, {"c": "dou-paragraph", "t": "2.3 Critérios de Aceitação e Rejeição"}, {"c": "dou-paragraph", "t": "2.3.1 Os critérios de aceitação e rejeição estão definidos na base normativa de referência, nos subitens 2.3 dos Anexos Específicos A e B, além dos seguintes."}, {"c": "dou-paragraph", "t": "2.3.2 O coletor acoplado é conforme se, após o ensaio de choque térmico, não apresentar fissuras, distorções e deformações."}, {"c": "dou-paragraph", "t": "2.3.3 O coletor acoplado é conforme se, no ensaio de verificação de penetração de chuva, após a repetição da pesagem, a variação de peso não for maior que 30 g/m² de área bruta do coletor acoplado."}, {"c": "dou-paragraph", "t": "2.3.4 A evidência de penetração de água no coletor acoplado após o choque térmico deve ser obtida por meio do ensaio de penetração de chuva, sendo que a constatação de penetração de água não constitui critério de reprovação."}, {"c": "dou-paragraph", "t": "2.3.5 O coletor acoplado é conforme se, após o ensaio de envelhecimento acelerado, o(s) material(is) polimérico(s) não apresentar(em) sinais de desgaste mecânico, como craqueamento e fissuras, ou de desgaste corrosivo."}, {"c": "dou-paragraph", "t": "2.3.6 A tolerância para o desvio da PMEe na Avaliação da Manutenção do modelo de sistema acoplado deve ser de ± 6,00% em relação aos resultados da etapa de Avaliação Inicial."}, {"c": "dou-paragraph", "t": "ANEXO A - MODELOS DE PLANILHAS DE ESPECIFICAÇÕES TÉCNICAS (PET)"}, {"c": "dou-paragraph", "t": "ANEXO B - DETALHAMENTO DOS PROCEDIMENTOS DE CÁLCULOS"}, {"c": "dou-paragraph", "t": "4. FAIXAS DE CLASSIFICAÇÃO DO DESEMPENHO TÉRMICO DOS SISTEMAS ACOPLADOS"}, {"c": "dou-paragraph", "t": "4.1 A classificação da eficiência para produção de energia dos sistemas acoplados deve ser determinada de acordo com a Tabela 2."}, {"c": "dou-paragraph", "t": "Tabela 2 - Faixas de Classificação para Sistemas Acoplados - Aplicação Banho"}, {"c": "", "t": "Faixas de Classificação Sistema Acoplado - Aplicação Banho"}, {"c": "", "t": "Classe"}, {"c": "", "t": "Produção Específica Mensal (kWh/mês.m 2 )"}, {"c": "", "t": "A"}, {"c": "", "t": "80,3 < PMEe"}, {"c": "", "t": "B"}, {"c": "", "t": "73,3 < PMEe < 80,3"}, {"c": "", "t": "C"}, {"c": "", "t": "66,3 < PMEe < 73,3"}, {"c": "", "t": "D"}, {"c": "", "t": "59,3 < PMEe < 66,3"}, {"c": "", "t": "E"}, {"c": "", "t": "52,3 < PMEe < 59,3"}, {"c": "dou-paragraph", "t": "ANEXO III SELO DE IDENTIFICAÇÃO DA CONFORMIDADE - ETIQUETA NACIONAL DE CONSERVAÇÃO DE ENERGIA"}, {"c": "dou-paragraph", "t": "1. CRITÉRIOS GERAIS"}, {"c": "dou-paragraph", "t": "1.1 O Selo de Identificação da Conformidade, na forma da Etiqueta Nacional de Conservação de Energia - ENCE, deve ser aposto no produto conforme estabelecido a seguir."}, {"c": "dou-paragraph", "t": "1.2 A ENCE deve ser aposta no equipamento, podendo, adicionalmente, também ser aposta ou impressa na embalagem primária do equipamento."}, {"c": "dou-paragraph", "t": "1.3 No coletor, a ENCE não pode ser aposta na área de abertura, a não ser se para fins de exposição no ponto de venda, em feiras e eventos."}, {"c": "nota", "t": "Republicada por ter saído, no DOU, nº 209, de 6-11-2026, Seção 1, págs. 42 a 54, com incorreção no original."}]});